function InsightsPageRedesigned({db,go}:{db:DB;go:(path:string)=>void}){
 const experiments=flattenExperiments(db.blends).sort((a,b)=>+new Date(a.date)-+new Date(b.date))
 const average=experiments.length?experiments.reduce((sum,experiment)=>sum+experiment.rating,0)/experiments.length:0
 const highest=experiments.length?Math.max(...experiments.map(experiment=>experiment.rating)):0
 const categoryPerformance=allCategories.map(category=>{const categoryExperiments=experiments.filter(experiment=>experiment.blend.category===category);return{name:category,rating:categoryExperiments.length?categoryExperiments.reduce((sum,experiment)=>sum+experiment.rating,0)/categoryExperiments.length:0,tests:categoryExperiments.length}}).filter(item=>item.tests)
 const timeline=experiments.map(experiment=>({date:new Date(experiment.date).toLocaleDateString('en-US',{month:'short',day:'numeric'}),rating:experiment.rating}))
 const taste=avgTaste(experiments as never)
 const mostExperimented=[...db.blends].sort((a,b)=>b.versions.flatMap(version=>version.experiments).length-a.versions.flatMap(version=>version.experiments).length)[0]
 let biggest:{blend:Blend;from:Version;to:Version;delta:number}|null=null
 for(const blend of db.blends)for(let index=1;index<blend.versions.length;index++){const from=blend.versions[index-1],to=blend.versions[index],delta=avgRating(to)-avgRating(from);if(!biggest||delta>biggest.delta)biggest={blend,from,to,delta}}
 const patterns=tasteInsights(experiments as never)
 return <div className="space-y-12 fade-up"><header className="border-b border-line pb-9"><div className="small-label">Personal experimentation analysis</div><h1 className="serif mt-2 text-5xl font-semibold sm:text-6xl">What have you learned?</h1><p className="mt-4 max-w-2xl text-sm leading-6 text-soft">Your ratings are a record of taste in motion. These patterns come from what you have actually made, not a generic recipe database.</p></header><section className="grid gap-5 border-b border-line pb-9 sm:grid-cols-2 xl:grid-cols-4"><div><div className="small-label">Blends</div><div className="mt-2 serif text-4xl">{db.blends.length}</div><div className="mt-1 text-xs text-soft">recipes in the lab</div></div><div><div className="small-label">Experiments</div><div className="mt-2 serif text-4xl">{experiments.length}</div><div className="mt-1 text-xs text-soft">tasting sessions recorded</div></div><div><div className="small-label">Average rating</div><div className="mt-2 serif text-4xl">{average?average.toFixed(1):'—'}</div><div className="mt-1 text-xs text-soft">across all sessions</div></div><div><div className="small-label">Highest rating</div><div className="mt-2 serif text-4xl">{highest?highest.toFixed(1):'—'}</div><div className="mt-1 text-xs text-soft">your best recorded pour</div></div></section><section className="grid gap-10 xl:grid-cols-[1.2fr_.8fr]"><div><div className="border-b border-line pb-4"><div className="small-label">Rating over time</div><h2 className="serif mt-2 text-3xl font-semibold">The shape of improvement</h2></div><div className="mt-6 h-[280px]">{timeline.length?<ResponsiveContainer width="100%" height="100%"><AreaChart data={timeline}><CartesianGrid stroke="#DDD2C3" vertical={false}/><XAxis dataKey="date" tick={{fontSize:10,fill:'#74665B'}} tickLine={false} axisLine={false}/><YAxis domain={[0,10]} tick={{fontSize:10,fill:'#74665B'}} tickLine={false} axisLine={false}/><Tooltip contentStyle={{borderRadius:8,border:'1px solid #DDD2C3',background:'#FFFDF9'}}/><Area type="monotone" dataKey="rating" stroke="#5D6B52" fill="#C5CEB8" fillOpacity={0.35} strokeWidth={3}/></AreaChart></ResponsiveContainer>:<div className="border-y border-line py-8 text-sm text-soft">Record a few experiments to reveal how your ratings move over time.</div>}</div></div><div className="surface-sheet p-6 sm:p-7"><div className="small-label">Blend DNA</div><h2 className="serif mt-2 text-3xl font-semibold">What you tend to notice</h2><div className="mt-3 h-[250px]"><ResponsiveContainer width="100%" height="100%"><RadarChart data={tasteLabels.slice(0,6).map(([key,label])=>({subject:label,value:Number((taste as any)[key]||0)}))} outerRadius="68%"><PolarGrid stroke="#DDD2C3"/><PolarAngleAxis dataKey="subject" tick={{fontSize:10,fill:'#74665B'}}/><PolarRadiusAxis domain={[0,10]} tick={false} axisLine={false}/><Radar name="Taste" dataKey="value" stroke="#5D6B52" fill="#C5CEB8" fillOpacity={0.5}/></RadarChart></ResponsiveContainer></div></div></section><section className="grid gap-10 border-t border-line pt-10 xl:grid-cols-[.8fr_1.2fr]"><div><div className="small-label">Patterns I have noticed</div><h2 className="serif mt-2 text-3xl font-semibold">Your own evidence</h2><div className="mt-5 space-y-4">{patterns.map((pattern,index)=><div key={index} className="border-l-2 border-caramel bg-subtle px-5 py-4 text-sm leading-6 text-soft">{pattern}</div>)}</div></div><div><div className="border-b border-line pb-4"><div className="small-label">Category performance</div><h2 className="serif mt-2 text-3xl font-semibold">Where your experiments land</h2></div><div className="mt-5 divide-y divide-line border-y border-line">{categoryPerformance.length?categoryPerformance.map(category=><div key={category.name} className="flex items-center gap-4 py-4"><div className="w-28 shrink-0 text-sm font-semibold">{category.name}</div><div className="h-2 flex-1 bg-subtle"><div className="h-full bg-green" style={{width:`${category.rating*10}%`}}/></div><div className="w-12 text-right font-semibold">{category.rating.toFixed(1)}</div><div className="w-16 text-right text-xs text-soft">{category.tests} test{category.tests===1?'':'s'}</div></div>):<div className="py-6 text-sm text-soft">Category patterns will appear after your first experiment.</div>}</div></div></section><section className="grid gap-10 border-t border-line pt-10 md:grid-cols-2"><div className="border-l-2 border-caramel bg-caramel-soft/20 p-6"><div className="small-label">Biggest improvement</div>{biggest?<><h2 className="serif mt-2 text-3xl font-semibold">{biggest.blend.name}</h2><div className="mt-5 flex items-center gap-3 text-lg"><span>v{biggest.from.number} · {avgRating(biggest.from).toFixed(1)}</span><ArrowRight size={17}/><span className="font-semibold">v{biggest.to.number} · {avgRating(biggest.to).toFixed(1)}</span></div><div className="mt-3 text-sm font-semibold text-caramel">{biggest.delta>=0?'+':''}{biggest.delta.toFixed(1)} rating change</div><p className="mt-4 text-sm leading-6 text-soft">A version-to-version story from your recorded ratings. It shows what happened after the recipe changed; it does not prove which change caused it.</p></>:<p className="mt-5 text-sm leading-6 text-soft">Create a second version to see your first improvement story.</p>}</div><div><div className="small-label">Most experimented</div><h2 className="serif mt-2 text-3xl font-semibold">The recipe with the most history</h2>{mostExperimented?<><div className="mt-5 flex items-center gap-3"><span className="text-3xl">{mostExperimented.emoji}</span><div><div className="font-semibold">{mostExperimented.name}</div><div className="mt-1 text-sm text-soft">{mostExperimented.versions.length} version{mostExperimented.versions.length===1?'':'s'} · {mostExperimented.versions.flatMap(version=>version.experiments).length} experiments</div></div></div><button className="btn-ghost mt-6 px-0 text-green" onClick={()=>{}}>Its evolution is in your blend archive <ChevronRight size={16}/></button></>:<p className="mt-5 text-sm text-soft">Your most experimented drink will appear here.</p>}</div></section></div>
}

function PantryEditModal({db,update,close,pantryId}:{db:DB;update:(d:DB)=>void;close:()=>void;pantryId?:string}){
 const editing=db.pantry.find(item=>item.id===pantryId)
 const [name,setName]=useState(editing?.name||'')
 const [quantity,setQuantity]=useState(editing?.quantity??100)
 const [unit,setUnit]=useState(editing?.unit||'ml')
 const [threshold,setThreshold]=useState(editing?.threshold??30)
 const [expiry,setExpiry]=useState(editing?.expiry?.slice(0,10)||'')
 const [error,setError]=useState('')
 function save(){if(!name.trim()){setError('Add an ingredient name.');return}const item:PantryItem={id:editing?.id||uid('pantry'),name:name.trim(),quantity,unit,threshold,expiry:expiry?new Date(expiry).toISOString():undefined};update({...db,pantry:editing?db.pantry.map(candidate=>candidate.id===editing.id?item:candidate):[item,...db.pantry]});close()}
 return <div><ModalHeader eyebrow={editing?'Edit ingredient':'Pantry'} title={editing?'Update ingredient':'Add ingredient'} close={close}/><p className="mt-3 text-sm leading-6 text-soft">Keep quantities current so MyBlend can suggest drinks you can actually make.</p><div className="mt-6 space-y-4"><label className="block text-sm font-semibold">Ingredient name<input autoFocus value={name} onChange={event=>{setName(event.target.value);setError('')}} className="ds-control mt-2 w-full" placeholder="Oat Milk"/></label><div className="grid grid-cols-2 gap-3"><label className="block text-sm font-semibold">Quantity<input type="number" min="0" value={quantity} onChange={event=>setQuantity(Number(event.target.value))} className="ds-control mt-2 w-full"/></label><label className="block text-sm font-semibold">Unit<input value={unit} onChange={event=>setUnit(event.target.value)} className="ds-control mt-2 w-full" placeholder="ml"/></label></div><div className="grid grid-cols-2 gap-3"><label className="block text-sm font-semibold">Low-stock threshold<input type="number" min="0" value={threshold} onChange={event=>setThreshold(Number(event.target.value))} className="ds-control mt-2 w-full"/></label><label className="block text-sm font-semibold">Expiry<span className="ml-2 text-xs font-normal text-soft">Optional</span><input type="date" value={expiry} onChange={event=>setExpiry(event.target.value)} className="ds-control mt-2 w-full"/></label></div>{error&&<div className="border-l-2 border-rose bg-rose/5 px-4 py-3 text-sm text-rose">{error}</div>}</div><div className="mt-7 flex justify-end gap-2 border-t border-line pt-5"><button className="btn-secondary" onClick={close}>Cancel</button><button className="btn-primary" onClick={save}><Check size={16}/> {editing?'Save changes':'Add Ingredient'}</button></div></div>
}

