const tasteLabels = [
  ['sweetness','Sweetness'],['strength','Strength'],['creaminess','Creaminess'],['richness','Richness'],
  ['refreshing','Refreshing'],['bitterness','Bitterness'],['acidity','Acidity'],['aroma','Aroma'],['texture','Texture']
] as const

function mkTaste(v:number):Taste { return {sweetness:v,strength:v,creaminess:v,richness:v,refreshing:v,bitterness:v,acidity:v,aroma:v,texture:v} }
function uid(prefix='id'){ return `${prefix}_${Math.random().toString(36).slice(2,10)}_${Date.now().toString(36)}` }
function clamp(v:number){ return Math.max(0,Math.min(10,v)) }
function nowMinus(days:number){ return new Date(Date.now()-days*86400000).toISOString() }
function fmtDate(s:string){ return new Date(s).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}) }
function currentAverage(blend:Blend){ const ex=blend.versions.flatMap(v=>v.experiments); return ex.length ? ex.reduce((a,e)=>a+e.rating,0)/ex.length : 0 }
function currentBest(blend:Blend){ return blend.versions.find(version=>version.isBest) ?? bestVersion(blend.versions) ?? [...blend.versions].sort((a,b)=>b.number-a.number)[0] }
function flattenExperiments(blends:Blend[]){ return blends.flatMap(b=>b.versions.flatMap(v=>v.experiments.map(e=>({ ...e, blend:b, version:v })))) }
function makeIngredient(name:string, amount:number, unit:string, brand?:string):Ingredient { return {id:uid('ing'),name,amount,unit,brand} }
function makeVersion(n:number,name:string,ingredients:Ingredient[],experiments:Experiment[],notes=''):Version { return {id:uid('v'),number:n,name,createdAt:nowMinus(30-n*5),notes,ingredients,preparation:'Shake or stir with ice. Serve immediately.',experiments,isBest:false} }

function demoExperiment(rating:number, days:number, taste:Partial<Taste>, notes:string):Experiment{
  return {id:uid('exp'),date:nowMinus(days),rating,taste:{...mkTaste(6),...taste},notes}
}

function seedDB():DB {
  const brown:Blend={id:'blend_brown',name:'Iced Brown Sugar Oat Latte',category:'Coffee',emoji:'☕',description:'A mellow oat latte with caramelized brown sugar and a clean coffee finish.',createdAt:nowMinus(42),favorite:true,versions:[]}
  brown.versions=[
    makeVersion(1,'The first pour',[makeIngredient('Espresso',36,'ml','House Arabica'),makeIngredient('Oat Milk',150,'ml','Oatly'),makeIngredient('Brown Sugar Syrup',18,'ml','Monin'),makeIngredient('Ice',120,'g')],[demoExperiment(6.8,32,{sweetness:7,strength:7,creaminess:6,richness:7,bitterness:5},'Good base, but syrup felt heavy.')],'Baseline recipe.'),
    makeVersion(2,'Less syrup',[makeIngredient('Espresso',36,'ml','House Arabica'),makeIngredient('Oat Milk',170,'ml','Oatly'),makeIngredient('Brown Sugar Syrup',13,'ml','Monin'),makeIngredient('Ice',110,'g')],[demoExperiment(7.6,24,{sweetness:6,strength:7,creaminess:8,richness:7,bitterness:4},'Smoother and less sweet.')],'Reduced syrup and added milk.'),
    makeVersion(3,'Coffee forward',[makeIngredient('Espresso',40,'ml','House Arabica'),makeIngredient('Oat Milk',170,'ml','Oatly'),makeIngredient('Brown Sugar Syrup',11,'ml','Monin'),makeIngredient('Ice',100,'g')],[demoExperiment(8.5,13,{sweetness:6,strength:9,creaminess:8,richness:8,bitterness:4},'Better coffee presence.')],'Increased espresso by 4ml.'),
    makeVersion(4,'Current favorite',[makeIngredient('Espresso',40,'ml','House Arabica'),makeIngredient('Oat Milk',180,'ml','Oatly'),makeIngredient('Brown Sugar Syrup',10,'ml','Monin'),makeIngredient('Ice',90,'g')],[demoExperiment(9.2,3,{sweetness:7,strength:9,creaminess:9,richness:9,bitterness:3,refreshing:6},'Balanced, creamy, and still coffee-forward.')],'Small milk increase and syrup reduction.')
  ]

  const matcha:Blend={id:'blend_matcha',name:'Iced Strawberry Matcha',category:'Matcha',emoji:'🍵',description:'Earthy ceremonial matcha layered with milk and bright strawberry.',createdAt:nowMinus(38),favorite:true,versions:[]}
  matcha.versions=[
    makeVersion(1,'First layer',[makeIngredient('Matcha',2,'g','Ippodo'),makeIngredient('Milk',180,'ml','Meiji'),makeIngredient('Strawberry Syrup',15,'ml','Torani'),makeIngredient('Ice',100,'g')],[demoExperiment(7.1,29,{sweetness:8,strength:6,creaminess:8,richness:6,bitterness:4,refreshing:8},'Pretty good, but strawberry dominated.')]),
    makeVersion(2,'Matcha lift',[makeIngredient('Matcha',2.5,'g','Ippodo'),makeIngredient('Milk',180,'ml','Meiji'),makeIngredient('Strawberry Syrup',12,'ml','Torani'),makeIngredient('Ice',95,'g')],[demoExperiment(8.2,18,{sweetness:7,strength:8,creaminess:8,richness:7,bitterness:4,refreshing:8},'More matcha presence.')]),
    makeVersion(3,'Less syrup',[makeIngredient('Matcha',2.5,'g','Ippodo'),makeIngredient('Milk',165,'ml','Meiji'),makeIngredient('Strawberry Syrup',8,'ml','Torani'),makeIngredient('Ice',85,'g')],[demoExperiment(9.1,6,{sweetness:6,strength:9,creaminess:9,richness:8,bitterness:3,refreshing:9},'This finally tastes like matcha first, strawberry second.')]),
  ]

  const cold:Blend={id:'blend_cold',name:'Vanilla Cold Brew',category:'Coffee',emoji:'🧊',description:'Cold brew with vanilla and a silky finish.',createdAt:nowMinus(20),favorite:false,versions:[]}
  cold.versions=[
    makeVersion(1,'Baseline',[makeIngredient('Cold Brew',220,'ml','Local Roaster'),makeIngredient('Vanilla Syrup',12,'ml','Monin'),makeIngredient('Milk',40,'ml','Full Cream'),makeIngredient('Ice',120,'g')],[demoExperiment(8.1,15,{sweetness:7,strength:8,creaminess:5,richness:7,bitterness:5,refreshing:8},'Clean and easy to drink.')]),
    makeVersion(2,'Creamier',[makeIngredient('Cold Brew',220,'ml','Local Roaster'),makeIngredient('Vanilla Syrup',10,'ml','Monin'),makeIngredient('Milk',70,'ml','Full Cream'),makeIngredient('Ice',110,'g')],[demoExperiment(8.7,5,{sweetness:7,strength:8,creaminess:8,richness:8,bitterness:4,refreshing:7},'Better texture, still coffee-forward.')]),
  ]

  const boba:Blend={id:'blend_boba',name:'Brown Sugar Boba Milk',category:'Boba',emoji:'🧋',description:'Chewy pearls, dark brown sugar and cold milk.',createdAt:nowMinus(11),favorite:false,versions:[]}
  boba.versions=[makeVersion(1,'First batch',[makeIngredient('Black Tapioca Pearls',100,'g','WuFuYuan'),makeIngredient('Brown Sugar',30,'g'),makeIngredient('Milk',160,'ml','Meiji'),makeIngredient('Ice',80,'g')],[demoExperiment(8.4,8,{sweetness:8,strength:6,creaminess:8,richness:9,bitterness:2,refreshing:5,texture:9},'Chewy and rich, a little sweet.')])]

  const pantry:PantryItem[]=[
    {id:uid('pantry'),name:'Oat Milk',quantity:500,unit:'ml',threshold:150,expiry:nowMinus(-9)},
    {id:uid('pantry'),name:'Matcha',quantity:30,unit:'g',threshold:8,expiry:nowMinus(-70)},
    {id:uid('pantry'),name:'Vanilla Syrup',quantity:200,unit:'ml',threshold:40},
    {id:uid('pantry'),name:'Brown Sugar Syrup',quantity:120,unit:'ml',threshold:30},
  ]
  const blends=[brown,matcha,cold,boba]
  const all=flattenExperiments(blends)
  const p=avgTaste(all as never)
  return {name:'Alex',blends,pantry,tasteProfile:p}
}

function loadDB():DB{
  try {
    const raw=window.localStorage.getItem('myblend_db_v2')
    if(raw){
      const parsed=JSON.parse(raw) as Partial<DB>
      if(Array.isArray(parsed.blends)&&Array.isArray(parsed.pantry)&&parsed.blends.every(blend=>Array.isArray(blend.versions)&&blend.versions.length>0))return {...parsed,name:typeof parsed.name==='string'?parsed.name:'Alex',tasteProfile:parsed.tasteProfile||mkTaste(0)} as DB
    }
  } catch {}
  const db=seedDB(); try{window.localStorage.setItem('myblend_db_v2',JSON.stringify(db))}catch{} return db
}

function saveDB(db:DB){ try{window.localStorage.setItem('myblend_db_v2',JSON.stringify(db))}catch{} }

export default function MyBlendApp({ initialModal }: { initialModal?:'create' } = {}) {
  const router=useRouter(); const pathname=usePathname()
  const [db,setDb]=useState<DB>({name:'Alex',blends:[],pantry:[],tasteProfile:mkTaste(0)})
  const [ready,setReady]=useState(false)
  const [modal,setModal]=useState<Modal>(initialModal==='create'?{type:'create',blendId:''}:null)
  const [mobileOpen,setMobileOpen]=useState(false)
  const [query,setQuery]=useState('')
  const [sort,setSort]=useState('newest')
  const [categoryFilter,setCategoryFilter]=useState<'all'|Category>('all')
  const [favoriteOnly,setFavoriteOnly]=useState(false)
  const [toast,setToast]=useState('')

  useEffect(()=>{ const loaded=loadDB(); setDb(loaded); setReady(true) },[])
  useEffect(()=>{ if(ready) saveDB(db) },[db,ready])
  useEffect(()=>{ if(!toast)return; const t=setTimeout(()=>setToast(''),2800); return()=>clearTimeout(t)},[toast])

  const routeParts=(pathname||'/').split('/').filter(Boolean)
  const activeKey = routeParts[0]==='blends'?'blends':(routeParts[0] as any)||'dashboard'
  const detailId = routeParts[0]==='blends' && routeParts[1] && routeParts[1]!=='new' ? routeParts[1] : null

  function go(path:string){ setMobileOpen(false); router.push(path) }
  function update(next:DB){ setDb(next); saveDB(next) }

  const filtered=useMemo(()=>{
    let list=[...db.blends]
    if(query.trim()) list=list.filter(b=>b.name.toLowerCase().includes(query.toLowerCase())||b.category.toLowerCase().includes(query.toLowerCase()))
    if(categoryFilter!=='all') list=list.filter(b=>b.category===categoryFilter)
    if(favoriteOnly) list=list.filter(b=>b.favorite)
    if(sort==='rating') list.sort((a,b)=>currentAverage(b)-currentAverage(a))
    else if(sort==='experiments') list.sort((a,b)=>b.versions.flatMap(v=>v.experiments).length-a.versions.flatMap(v=>v.experiments).length)
    else if(sort==='oldest') list.sort((a,b)=>+new Date(a.createdAt)-+new Date(b.createdAt))
    else list.sort((a,b)=>+new Date(b.createdAt)-+new Date(a.createdAt))
    return list
  },[db.blends,query,categoryFilter,favoriteOnly,sort])

  if(!ready) return <div className="min-h-screen bg-cream flex items-center justify-center"><div className="text-center"><div className="mx-auto mb-4 h-12 w-12 rounded-2xl bg-espresso text-paper grid place-items-center"><Beaker size={22}/></div><div className="serif text-3xl">Opening your Blend Lab…</div><div className="text-sm text-soft mt-2">Preparing your saved experiments.</div></div></div>

  const detailBlend=detailId ? db.blends.find(b=>b.id===detailId) : null

  const activeItem=navItems.find(item=>item.key===activeKey) ?? navItems[0]
  const profileName=db.name.trim()||'Alex'
  const profileInitial=profileName.charAt(0).toUpperCase()

  return <div className="min-h-screen bg-cream text-espresso">
    <div className="desktop-only fixed inset-y-0 left-0 z-30 w-[248px] border-r border-line bg-paper">
      <Sidebar active={activeKey} go={go} create={()=>setModal({type:'create',blendId:''})} name={profileName} initial={profileInitial}/>
    </div>

    <div className="lg:pl-[248px]">
      <header className="sticky top-0 z-20 flex min-h-[72px] items-center justify-between gap-4 border-b border-line bg-cream/95 px-5 py-3 sm:px-8 lg:px-10 xl:px-12">
        <div className="mobile-only flex min-w-0 items-center gap-3"><button className="btn-ghost p-2" onClick={()=>setMobileOpen(v=>!v)} aria-label="Open navigation"><Menu size={20}/></button><div className="min-w-0"><div className="serif truncate text-xl font-semibold">MyBlend</div><div className="truncate text-[10px] font-semibold uppercase tracking-[.14em] text-soft">{activeItem.label}</div></div></div>
        <div className="desktop-only min-w-0"><div className="small-label">My workspace / {activeItem.label}</div><div className="mt-1 flex items-center gap-2"><span className="serif text-2xl font-semibold">{activeItem.label}</span><span className="text-sm text-soft">Personal drink lab</span></div></div>
        <div className="flex flex-1 justify-end gap-2 sm:gap-3">
          <div className="hidden max-w-[310px] flex-1 items-center gap-2 rounded-2xl border border-line bg-paper px-3 py-2 sm:flex"><Search size={16} className="text-soft"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search your blends…" className="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-soft/70"/></div>
          <button className="btn-ghost hidden sm:inline-flex" onClick={()=>setToast('You are in Demo Mode — your data stays in this browser.') }><CircleHelp size={16}/> Demo mode</button>
          <button className="btn-ghost p-2" aria-label="Notifications"><Bell size={19}/></button>
          <button className="flex h-10 w-10 items-center justify-center rounded-xl border border-line bg-paper font-extrabold text-green" onClick={()=>go('/settings')} aria-label="Settings">{profileInitial}</button>
        </div>
      </header>

      {mobileOpen && <div className="mobile-only fixed inset-0 z-40 bg-espresso/25" onClick={()=>setMobileOpen(false)}><div className="absolute left-0 top-0 h-full w-[min(86vw,320px)] bg-paper p-5 shadow-float" onClick={e=>e.stopPropagation()}><Sidebar active={activeKey} go={go} create={()=>setModal({type:'create',blendId:''})} name={profileName} initial={profileInitial}/></div></div>}

      <main className="mx-auto w-full max-w-[1680px] px-5 pb-28 pt-7 sm:px-8 sm:pt-9 lg:px-10 lg:pb-10 lg:pt-10 xl:px-12">
        {detailBlend ? <BlendDetail blend={detailBlend} db={db} update={update} setModal={setModal} go={go} toast={setToast}/> : <>
          {activeKey==='dashboard' && <Dashboard db={db} go={go} setModal={setModal} toast={setToast}/>} 
          {activeKey==='blends' && <BlendsPage blends={filtered} query={query} setQuery={setQuery} sort={sort} setSort={setSort} categoryFilter={categoryFilter} setCategoryFilter={setCategoryFilter} favoriteOnly={favoriteOnly} setFavoriteOnly={setFavoriteOnly} go={go} db={db} update={update}/>} 
          {activeKey==='experiments' && <ExperimentsPage db={db} go={go}/>} 
          {activeKey==='pantry' && <PantryPage db={db} setModal={setModal} update={update}/>} 
          {activeKey==='insights' && <InsightsPageRedesigned db={db} go={go}/>} 
          {activeKey==='settings' && <SettingsPage db={db} update={update} toast={setToast}/>} 
        </>}
      </main>
    </div>

    <MobileNav active={activeKey} go={go} setModal={()=>setModal({type:'create',blendId:''})}/>
    <AnimatePresence>{toast && <motion.div initial={{y:30,opacity:0}} animate={{y:0,opacity:1}} exit={{y:20,opacity:0}} className="fixed bottom-24 left-1/2 z-[70] -translate-x-1/2 rounded-full bg-espresso px-5 py-3 text-sm font-bold text-paper shadow-float lg:bottom-8">{toast}</motion.div>}</AnimatePresence>
    <ModalHost modal={modal} db={db} update={update} close={()=>setModal(null)} toast={setToast}/>
  </div>
}

function Sidebar({active,go,create,name,initial}:{active:string;go:(p:string)=>void;create:()=>void;name:string;initial:string}){
  return <div className="flex h-full flex-col px-6 py-7"><div className="mb-12 flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-lg bg-espresso text-paper"><Beaker size={17}/></div><div><div className="serif text-xl font-semibold leading-none">MyBlend</div><div className="mt-1 text-[9px] font-semibold uppercase tracking-[.16em] text-soft">Personal drink lab</div></div></div><button className="btn-primary mb-10 w-full rounded-xl py-3" onClick={create}><Plus size={17}/> Create Blend</button><div className="small-label px-1 pb-3">Workbench</div><nav className="space-y-1">{navItems.map(n=>{const Icon=n.icon;const selected=active===n.key;return <button key={n.key} onClick={()=>go(`/${n.key==='dashboard'?'':n.key}`||'/')} aria-current={selected?'page':undefined} className={`group relative flex w-full items-center gap-3 border-l-2 px-3 py-3 text-left text-sm transition ${selected?'border-caramel font-semibold text-espresso':'border-transparent font-medium text-soft hover:border-line hover:text-espresso'}`}><Icon size={17} strokeWidth={selected?2.25:1.8}/><span>{n.label}</span>{n.key==='experiments'&&<span className="ml-auto text-[9px] font-semibold uppercase tracking-[.12em] text-caramel">New</span>}</button>})}</nav><div className="mt-auto space-y-5"><div className="border-t border-line pt-5"><div className="small-label">Today</div><div className="mt-2 serif text-2xl font-semibold">One variable.</div><p className="mt-1 text-xs leading-relaxed text-soft">Change one thing, record the result, then let the pattern reveal itself.</p></div><button className="btn-ghost w-full justify-start rounded-lg px-1" onClick={()=>go('/settings')}><Settings size={17}/> Settings</button><div className="flex items-center gap-3 border-t border-line pt-4"><div className="grid h-8 w-8 place-items-center rounded-full bg-sage text-xs font-bold text-green">{initial}</div><div className="min-w-0"><div className="truncate text-xs font-semibold">{name}'s lab</div><div className="text-[10px] text-soft">Demo workspace</div></div></div></div></div>
}

function MobileNav({active,go,setModal}:{active:string;go:(p:string)=>void;setModal:()=>void}){
 return <nav className="mobile-only fixed bottom-0 left-0 right-0 z-50 border-t border-line bg-paper px-3 pb-[max(.65rem,env(safe-area-inset-bottom))] pt-2"><div className="mx-auto grid max-w-xl grid-cols-5 items-end">{[
  {k:'dashboard',l:'Home',i:Home},{k:'blends',l:'Blends',i:BookOpen},{k:'+',l:'Create',i:Plus},{k:'pantry',l:'Pantry',i:Package},{k:'insights',l:'Insights',i:Activity}
 ].map(x=>{const I=x.i;return x.k==='+'?<button key={x.k} onClick={setModal} className="mx-auto -mt-6 flex h-14 w-14 flex-col items-center justify-center gap-0.5 rounded-xl bg-espresso text-paper shadow-float"><I size={21}/><span className="text-[9px] font-semibold">{x.l}</span></button>:<button key={x.k} onClick={()=>go(x.k==='dashboard'?'/':`/${x.k}`)} aria-current={active===x.k?'page':undefined} className={`flex flex-col items-center gap-1 px-2 py-2 text-[10px] font-semibold transition ${active===x.k?'text-green':'text-soft'}`}><I size={18} strokeWidth={active===x.k?2.25:1.8}/>{x.l}</button>})}</div></nav>
}

function Dashboard({db,go,setModal,toast}:{db:DB;go:(p:string)=>void;setModal:(m:Modal)=>void;toast:(s:string)=>void}){
 const experiments=flattenExperiments(db.blends).sort((a,b)=>+new Date(b.date)-+new Date(a.date))
 const latest=experiments[0]
 const focusBlend=latest?.blend ?? db.blends[0]
 const focusVersion=latest?.version ?? (focusBlend ? currentBest(focusBlend) : undefined)
 const previousVersion=focusBlend&&focusVersion ? focusBlend.versions.find(v=>v.number===focusVersion.number-1) : undefined
 const focusRating=latest?.rating ?? (focusVersion ? avgRating(focusVersion) : 0)
 const previousRating=previousVersion ? avgRating(previousVersion) : 0
 const ratingDelta=previousRating && focusRating ? focusRating-previousRating : null
 const focusRecommendation=latest&&focusVersion&&focusBlend ? recommend(latest,focusVersion,previousVersion,db.pantry) : null
 const average=experiments.length ? experiments.reduce((sum,experiment)=>sum+experiment.rating,0)/experiments.length : 0
 const bestDrink=[...db.blends].sort((a,b)=>currentAverage(b)-currentAverage(a))[0]
 const focusCandidates=db.blends.filter(blend=>blend.versions.length<4).slice(0,3)
 const lowStock=db.pantry.filter(item=>item.quantity<=item.threshold)
 const availableIngredients=db.pantry.filter(item=>item.quantity>item.threshold).slice(0,4)
 const dna=focusBlend ? avgTaste(focusBlend.versions.flatMap(version=>version.experiments)) : db.tasteProfile
 const activity=[
   ...db.blends.map(blend=>({id:`created-${blend.id}`,date:blend.createdAt,label:'Created blend',title:blend.name,detail:blend.category,blendId:blend.id,icon:Plus})),
   ...experiments.map(experiment=>({id:`tested-${experiment.id}`,date:experiment.date,label:`Tested v${experiment.version.number}`,title:experiment.blend.name,detail:experiment.notes||`${experiment.rating.toFixed(1)}/10 rating`,blendId:experiment.blend.id,icon:FlaskConical})),
   ...db.blends.flatMap(blend=>blend.versions.slice(1).map(version=>({id:`variation-${version.id}`,date:version.createdAt,label:'Created variation',title:blend.name,detail:`v${version.number} · ${version.name}`,blendId:blend.id,icon:GitCompare}))),
   ...db.blends.flatMap(blend=>blend.versions.filter(version=>version.isBest).map(version=>({id:`best-${version.id}`,date:version.createdAt,label:'Marked best version',title:blend.name,detail:`v${version.number} · ${version.name}`,blendId:blend.id,icon:Star}))),
  ...db.blends.flatMap(blend=>blend.versions.slice(1).flatMap(version=>{const prior=blend.versions.find(candidate=>candidate.number===version.number-1);const change=prior?avgRating(version)-avgRating(prior):0;return change>0?[{id:`improved-${version.id}`,date:version.createdAt,label:'Increased rating',title:blend.name,detail:`+${change.toFixed(1)} after v${version.number}`,blendId:blend.id,icon:TrendingUp}]:[]})),
 ].sort((a,b)=>+new Date(b.date)-+new Date(a.date)).slice(0,8) as Array<{id:string;date:string;label:string;title:string;detail:string;blendId:string;icon:any}>

 return <div className="space-y-12 fade-up">
   <section className="border-b border-line pb-10 pt-2"><div className="small-label">Your Blend Lab</div><div className="mt-3 flex flex-col justify-between gap-7 xl:flex-row xl:items-end"><div><h1 className="serif max-w-3xl text-5xl leading-[1.05] sm:text-6xl">Good evening, {db.name}.<br/><span className="text-soft">What are you working on today?</span></h1><p className="mt-5 max-w-xl text-sm leading-6 text-soft">A quiet place to keep the experiments worth remembering and make the next pour a little more intentional.</p></div><div className="flex shrink-0 flex-wrap gap-3"><button className="btn-primary" onClick={()=>setModal({type:'create',blendId:''})}><Plus size={18}/> Create Blend</button><button className="btn-secondary" onClick={()=>toast(focusRecommendation?.experimentIdea||'Start with one small variable in your next experiment.')}><Lightbulb size={17}/> What should I make?</button></div></div></section>

   <section className="grid gap-8 xl:grid-cols-[1.35fr_.65fr]">
     <div className="surface-highlight p-6 sm:p-8"><div className="flex flex-col justify-between gap-8 sm:flex-row"><div><div className="small-label !text-caramel-soft">Current focus</div>{focusBlend?<><div className="mt-5 flex items-start gap-4"><div className="text-4xl">{focusBlend.emoji}</div><div><div className="text-xs font-semibold uppercase tracking-[.12em] text-paper/60">{focusBlend.category}</div><h2 className="serif mt-1 text-3xl font-semibold sm:text-4xl">{focusBlend.name}</h2></div></div><div className="mt-7 flex flex-wrap items-end gap-x-8 gap-y-4"><div><div className="text-xs text-paper/60">Current version</div><div className="mt-1 text-lg font-semibold">v{focusVersion?.number ?? '—'} · {focusVersion?.name}</div></div><div><div className="text-xs text-paper/60">Current rating</div><div className="mt-1 serif text-4xl">{focusRating?focusRating.toFixed(1):'—'}<span className="ml-1 text-sm font-sans text-paper/60">/10</span></div></div>{ratingDelta!==null&&<div><div className="text-xs text-paper/60">Since previous version</div><div className={`mt-1 text-lg font-semibold ${ratingDelta>=0?'text-caramel-soft':'text-rose'}`}>{ratingDelta>=0?'+':''}{ratingDelta.toFixed(1)}</div></div>}</div></>:<div className="mt-6 text-sm text-paper/70">Create a blend to give your lab a current focus.</div>}</div>{focusBlend&&<div className="flex shrink-0 items-start gap-2"><button className="rounded-lg bg-caramel-soft px-4 py-3 text-sm font-semibold text-espresso" onClick={()=>setModal({type:'experiment',blendId:focusBlend.id})}><Beaker size={16}/> Make Again</button><button className="rounded-lg border border-paper/20 px-4 py-3 text-sm font-semibold text-paper" onClick={()=>go(`/blends/${focusBlend.id}`)}>Continue <ArrowRight size={16}/></button></div>}</div>{focusBlend&&<div className="mt-8 border-t border-paper/15 pt-5"><div className="text-xs font-semibold uppercase tracking-[.12em] text-paper/60">Latest experiment note</div><p className="mt-2 max-w-2xl text-sm leading-6 text-paper/80">{latest?.notes||focusVersion?.notes||'No experiment note yet. Make the drink and record what you notice.'}</p></div>}</div>
     <div className="surface-sheet flex flex-col justify-between p-6 sm:p-7"><div><div className="small-label">Blend lab</div><h2 className="serif mt-2 text-3xl font-semibold">The work so far</h2></div><dl className="mt-8 divide-y divide-line"><div className="flex items-baseline justify-between py-4 first:pt-0"><dt className="text-sm text-soft">Total blends</dt><dd className="serif text-3xl">{db.blends.length}</dd></div><div className="flex items-baseline justify-between py-4"><dt className="text-sm text-soft">Experiments</dt><dd className="serif text-3xl">{experiments.length}</dd></div><div className="flex items-baseline justify-between py-4"><dt className="text-sm text-soft">Average rating</dt><dd className="serif text-3xl">{average?average.toFixed(1):'—'}</dd></div><div className="py-4 last:pb-0"><dt className="text-sm text-soft">Best-rated drink</dt><dd className="mt-1 font-semibold">{bestDrink?.name||'—'}{bestDrink&&<span className="ml-2 text-sm font-normal text-soft">{currentAverage(bestDrink).toFixed(1)}/10</span>}</dd></div></dl></div>
   </section>

   <section className="grid gap-10 xl:grid-cols-[1.15fr_.85fr]">
     <div><div className="flex items-end justify-between gap-4 border-b border-line pb-4"><div><div className="small-label">Continue experimenting</div><h2 className="serif mt-2 text-3xl font-semibold">Still in motion</h2></div><button className="btn-ghost" onClick={()=>go('/experiments')}>View lab <ArrowRight size={16}/></button></div><div className="divide-y divide-line">{focusCandidates.map(blend=>{const version=currentBest(blend);const score=currentAverage(blend);const blendExperiments=blend.versions.flatMap(item=>item.experiments).sort((a,b)=>+new Date(b.date)-+new Date(a.date));const suggestion=blendExperiments[0]?.recommendation||'Make one small change, then record what you notice.';return <div key={blend.id} className="group py-5 first:pt-6"><div className="flex items-start justify-between gap-5"><div className="min-w-0"><div className="flex items-center gap-3"><span className="text-2xl">{blend.emoji}</span><div><div className="text-xs uppercase tracking-[.12em] text-soft">{blend.category}</div><h3 className="mt-1 font-semibold">{blend.name}</h3></div></div><div className="mt-4 grid gap-3 text-xs text-soft sm:grid-cols-3"><span><strong className="font-semibold text-espresso">{score?score.toFixed(1):'—'}/10</strong> current score</span><span><strong className="font-semibold text-espresso">{blend.versions.length}</strong> versions</span><span>Last test <strong className="font-semibold text-espresso">{blendExperiments[0]?fmtDate(blendExperiments[0].date):'Not yet'}</strong></span></div><div className="mt-3 text-sm text-soft"><span className="font-semibold text-espresso">Next:</span> {suggestion}</div></div><button className="btn-ghost shrink-0 px-0 text-green opacity-70 transition group-hover:opacity-100" onClick={()=>go(`/blends/${blend.id}`)} aria-label={`Open ${blend.name}`}><ChevronRight size={18}/></button></div></div>})}{focusCandidates.length===0&&<div className="py-8 text-sm text-soft">Your blends are all well into their evolution. Start a new variation when you are ready.</div>}</div></div>
     <div><div className="border-b border-line pb-4"><div className="small-label">Recent activity</div><h2 className="serif mt-2 text-3xl font-semibold">What happened lately</h2></div><div className="relative mt-2 border-l border-line pl-6">{activity.map(entry=>{const Icon=entry.icon;return <button key={entry.id} className="group relative block w-full py-4 text-left first:pt-5" onClick={()=>go(`/blends/${entry.blendId}`)}><span className="absolute -left-[31px] top-6 grid h-3 w-3 place-items-center rounded-full border-2 border-cream bg-caramel"/><div className="flex items-start gap-3"><Icon size={16} className="mt-0.5 shrink-0 text-green"/><div className="min-w-0"><div className="text-xs text-soft">{entry.label} · {fmtDate(entry.date)}</div><div className="mt-1 font-semibold group-hover:text-green">{entry.title}</div><div className="mt-1 truncate text-xs text-soft">{entry.detail}</div></div></div></button>})}{activity.length===0&&<div className="py-8 text-sm text-soft">Your activity will appear here as the lab begins to fill.</div>}</div></div>
   </section>

   <section className="grid gap-10 border-t border-line pt-10 xl:grid-cols-[.9fr_1.1fr]">
     <div className="surface-sheet p-6 sm:p-7"><div className="flex items-end justify-between gap-4"><div><div className="small-label">Taste profile</div><h2 className="serif mt-2 text-3xl font-semibold">Your Blend DNA</h2></div><button className="btn-ghost px-0 text-green" onClick={()=>go('/insights')}>Full profile <ArrowRight size={16}/></button></div><p className="mt-3 max-w-sm text-sm leading-6 text-soft">A living sketch of what you notice and rate in the drinks you make.</p><div className="mt-4 h-[260px]"><ResponsiveContainer width="100%" height="100%"><RadarChart data={tasteLabels.slice(0,6).map(([key,label])=>({subject:label,value:Number((dna as any)[key]||0)}))} outerRadius="68%"><PolarGrid stroke="#DDD2C3"/><PolarAngleAxis dataKey="subject" tick={{fontSize:10,fill:'#74665B'}}/><PolarRadiusAxis domain={[0,10]} tick={false} axisLine={false}/><Radar name="Taste" dataKey="value" stroke="#5D6B52" fill="#C5CEB8" fillOpacity={0.5}/></RadarChart></ResponsiveContainer></div></div>
     <div><div className="border-b border-line pb-4"><div className="small-label">Pantry snapshot</div><h2 className="serif mt-2 text-3xl font-semibold">Use what is close</h2></div><div className="grid gap-8 pt-6 sm:grid-cols-2"><div><div className="text-sm font-semibold">Low stock</div>{lowStock.length?<div className="mt-4 space-y-3">{lowStock.map(item=><div key={item.id} className="flex items-center justify-between border-b border-line pb-3 text-sm"><span>{item.name}</span><span className="text-rose">{item.quantity}{item.unit} left</span></div>)}</div>:<div className="mt-4 text-sm leading-6 text-soft">Nothing needs restocking right now.</div>}</div><div><div className="text-sm font-semibold">Available for experiments</div>{availableIngredients.length?<div className="mt-4 space-y-3">{availableIngredients.map(item=><div key={item.id} className="flex items-center justify-between border-b border-line pb-3 text-sm"><span>{item.name}</span><span className="text-soft">{item.quantity}{item.unit}</span></div>)}</div>:<div className="mt-4 text-sm leading-6 text-soft">Add a few ingredients to make recommendations more useful.</div>}</div></div><button className="btn-ghost mt-7 px-0 text-green" onClick={()=>go('/pantry')}>Open pantry <ArrowRight size={16}/></button></div>
   </section>
 </div>
}

function RecommendationCard({blend,latest,db}:{blend:Blend;latest:any;db:DB}){
 const rec=recommend(latest,latest.version,blend.versions.find(v=>v.number===latest.version.number-1),db.pantry)
 return <div className="mt-4 rounded-3xl bg-cream p-5"><div className="flex items-start gap-3"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-2xl bg-caramel-soft"><Lightbulb size={18}/></div><div><div className="font-extrabold">{rec.summary}</div><p className="mt-2 text-sm leading-6 text-soft">{rec.suggestions[0]}</p>{rec.suggestions[1]&&<p className="mt-1 text-sm leading-6 text-soft">{rec.suggestions[1]}</p>}</div></div><div className="mt-4 rounded-2xl bg-paper p-4"><div className="small-label">Experiment idea</div><div className="mt-1 text-sm font-bold">{rec.experimentIdea}</div></div></div>
}

function Stat({icon:Icon,label,value,note}:{icon:any;label:string;value:string;note:string}){return <div className="card p-5"><div className="flex items-center justify-between"><div className="small-label">{label}</div><div className="grid h-9 w-9 place-items-center rounded-xl bg-cream"><Icon size={17} className="text-green"/></div></div><div className="mt-3 serif text-3xl font-semibold">{value}</div><div className="mt-1 truncate text-xs text-soft">{note}</div></div>}

function BlendsPage({blends,query,setQuery,sort,setSort,categoryFilter,setCategoryFilter,favoriteOnly,setFavoriteOnly,go,db,update}:{blends:Blend[];query:string;setQuery:(v:string)=>void;sort:string;setSort:(v:string)=>void;categoryFilter:'all'|Category;setCategoryFilter:(v:'all'|Category)=>void;favoriteOnly:boolean;setFavoriteOnly:(v:boolean)=>void;go:(p:string)=>void;db:DB;update:(d:DB)=>void}){
 const [view,setView]=useState<'grid'|'list'>('grid')
 const total=blends.length
 const hasFilters=Boolean(query.trim())||categoryFilter!=='all'||favoriteOnly
 function resetFilters(){setQuery('');setCategoryFilter('all');setFavoriteOnly(false)}
 return <div className="space-y-10 fade-up">
  <header className="flex flex-col justify-between gap-6 border-b border-line pb-8 lg:flex-row lg:items-end"><div><div className="small-label">Recipe archive</div><h1 className="serif mt-2 text-5xl font-semibold">My Blends</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-soft">A living record of drinks worth making again, changing carefully, and remembering.</p></div><button className="btn-primary self-start lg:self-auto" onClick={()=>go('/blends/new')}><Plus size={18}/> Create Blend</button></header>
  <section className="space-y-4"><div className="flex flex-col gap-3 lg:flex-row lg:items-center"><label className="ds-focus flex min-h-11 flex-1 items-center gap-3 rounded-lg border border-line bg-paper px-3"><Search size={17} className="text-soft"/><span className="sr-only">Search blends</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search your archive…" className="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-soft/70"/></label><div className="flex flex-wrap items-center gap-2"><select aria-label="Sort blends" value={sort} onChange={e=>setSort(e.target.value)} className="ds-control text-sm font-semibold"><option value="newest">Newest first</option><option value="rating">Highest rated</option><option value="experiments">Most experimented</option><option value="oldest">Oldest first</option></select><button onClick={()=>setFavoriteOnly(!favoriteOnly)} className={`ds-button ds-button-secondary ${favoriteOnly?'!border-green !bg-sage/30':''}`}><Heart size={15} fill={favoriteOnly?'currentColor':'none'}/> Favorites</button><div className="flex border-l border-line pl-2"><button aria-label="Editorial grid view" title="Editorial grid" onClick={()=>setView('grid')} className={`ds-button p-2 ${view==='grid'?'ds-button-secondary':'ds-button-quiet'}`}><LayoutGrid size={17}/></button><button aria-label="Compact list view" title="Compact list" onClick={()=>setView('list')} className={`ds-button p-2 ${view==='list'?'ds-button-secondary':'ds-button-quiet'}`}><List size={17}/></button></div></div></div><div className="flex items-center gap-2 overflow-x-auto pb-1"><span className="small-label shrink-0">Browse by</span><button onClick={()=>setCategoryFilter('all')} className={`border-b-2 px-2 py-2 text-xs font-semibold transition ${categoryFilter==='all'?'border-caramel text-espresso':'border-transparent text-soft hover:text-espresso'}`}>All</button>{allCategories.map(category=><button key={category} onClick={()=>setCategoryFilter(category)} className={`shrink-0 border-b-2 px-2 py-2 text-xs font-semibold transition ${categoryFilter===category?'border-caramel text-espresso':'border-transparent text-soft hover:text-espresso'}`}>{category}</button>)}</div></section>
  {total===0?<EmptyState icon={hasFilters?Search:BookOpen} title={hasFilters?'No blends match this view.':'Your archive is waiting.'} description={hasFilters?'Try a different search or clear the filters.':'Create your first drink and give the experiment a place to live.'} action={hasFilters?'Clear filters':'Create My First Blend'} onClick={hasFilters?resetFilters:()=>go('/blends/new')}/>:view==='grid'?<div className="grid gap-x-6 gap-y-8 sm:grid-cols-2 xl:grid-cols-12">{blends.map((blend,index)=><BlendCard key={blend.id} b={blend} go={go} update={update} db={db} view="grid" featured={index===0} className={index===0?'xl:col-span-7':index===1?'xl:col-span-5':'xl:col-span-4'}/>)}</div>:<div className="border-y border-line">{blends.map(blend=><BlendCard key={blend.id} b={blend} go={go} update={update} db={db} view="list"/>)}</div>}
 </div>
}

function categoryAccent(category:Category){
 if(category==='Coffee')return 'border-l-caramel'
 if(category==='Matcha')return 'border-l-green'
 if(category==='Boba'||category==='Smoothies')return 'border-l-rose'
 if(category==='Mocktails')return 'border-l-olive'
 return 'border-l-soft'
}

function BlendCard({b,go,update,db,view='grid',featured=false,className}:{b:Blend;go:(p:string)=>void;update:(d:DB)=>void;db:DB;view?:'grid'|'list';featured?:boolean;className?:string}){
 const best=currentBest(b); const current=[...b.versions].sort((a,version)=>version.number-a.number)[0]; const rating=currentAverage(b); const experiments=b.versions.flatMap(version=>version.experiments); const lastUpdated=[...experiments].sort((a,version)=>+new Date(version.date)-+new Date(a.date))[0]?.date||current?.createdAt||b.createdAt
 function toggleFavorite(e:React.MouseEvent){e.stopPropagation();update({...db,blends:db.blends.map(x=>x.id===b.id?{...x,favorite:!x.favorite}:x)})}
 if(view==='list')return <motion.div whileHover={{x:3}} className={`group border-l-2 ${categoryAccent(b.category)} border-b border-line py-4 pl-4 sm:pl-5`}><div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:gap-8"><button className="min-w-0 flex-1 text-left" onClick={()=>go(`/blends/${b.id}`)}><div className="flex items-start gap-3"><span className="mt-0.5 text-xl">{b.emoji}</span><div className="min-w-0"><div className="small-label">{b.category}</div><h3 className="mt-1 truncate font-semibold">{b.name}</h3><p className="mt-1 truncate text-sm text-soft">{b.description}</p></div></div></button><div className="grid grid-cols-2 gap-x-8 gap-y-2 text-xs text-soft sm:grid-cols-4 lg:w-[52%] lg:grid-cols-4"><div><div className="small-label">Current</div><div className="mt-1 font-semibold text-espresso">v{current?.number||'—'}</div></div><div><div className="small-label">Best rating</div><div className="mt-1 font-semibold text-espresso">{rating?rating.toFixed(1):'—'}<span className="font-normal text-soft">/10</span></div></div><div><div className="small-label">Experiments</div><div className="mt-1 font-semibold text-espresso">{experiments.length}</div></div><div><div className="small-label">Updated</div><div className="mt-1 font-semibold text-espresso">{fmtDate(lastUpdated)}</div></div></div><div className="flex items-center gap-2"><button onClick={toggleFavorite} className="btn-ghost p-2" aria-label={b.favorite?'Remove from favorites':'Add to favorites'}><Heart size={17} fill={b.favorite?'currentColor':'none'} className={b.favorite?'text-rose':''}/></button><button className="btn-ghost p-2" onClick={()=>go(`/blends/${b.id}`)} aria-label={`Open ${b.name}`}><ChevronRight size={17}/></button></div></div></motion.div>
 return <motion.article whileHover={{y:-3}} className={`surface-sheet group overflow-hidden border-l-2 ${categoryAccent(b.category)} ${featured?'xl:min-h-[300px]':''} ${className||''}`}><div className={`flex items-start justify-between gap-3 px-5 pt-5 ${featured?'sm:px-7 sm:pt-7':''}`}><button className="min-w-0 text-left" onClick={()=>go(`/blends/${b.id}`)}><div className="small-label">{b.category}</div><h3 className={`serif mt-2 font-semibold leading-tight ${featured?'text-3xl sm:text-4xl':'text-2xl'}`}>{b.name}</h3></button><button onClick={toggleFavorite} className="btn-ghost shrink-0 p-2" aria-label={b.favorite?'Remove from favorites':'Add to favorites'}><Heart size={17} fill={b.favorite?'currentColor':'none'} className={b.favorite?'text-rose':''}/></button></div><button className="block w-full text-left" onClick={()=>go(`/blends/${b.id}`)}><div className={`px-5 pb-5 ${featured?'sm:px-7 sm:pb-7':''}`}><div className="mt-4 flex items-baseline gap-3"><span className="serif text-4xl font-semibold">{rating?rating.toFixed(1):'—'}</span><span className="text-xs text-soft">best rating / 10</span></div><p className="mt-4 line-clamp-2 text-sm leading-6 text-soft">{b.description}</p><div className="mt-6 grid grid-cols-2 gap-x-4 gap-y-4 border-t border-line pt-4 text-xs"><div><div className="small-label">Current version</div><div className="mt-1 font-semibold text-espresso">v{current?.number||'—'} · {current?.name||'—'}</div></div><div><div className="small-label">Experiments</div><div className="mt-1 font-semibold text-espresso">{experiments.length}</div></div><div><div className="small-label">Last updated</div><div className="mt-1 font-semibold text-espresso">{fmtDate(lastUpdated)}</div></div><div><div className="small-label">Best version</div><div className="mt-1 font-semibold text-espresso">v{best?.number||'—'}</div></div></div><div className="mt-5 flex items-center justify-between text-xs font-semibold text-green"><span>Open archive entry</span><ChevronRight size={16}/></div></div></button></motion.article>
}

function BlendDetail({blend,db,update,setModal,go,toast}:{blend:Blend;db:DB;update:(d:DB)=>void;setModal:(m:Modal)=>void;go:(p:string)=>void;toast:(s:string)=>void}){
 const [selected,setSelected]=useState(currentBest(blend).id)
 const version=blend.versions.find(item=>item.id===selected) ?? currentBest(blend)
 const current=[...blend.versions].sort((a,b)=>b.number-a.number)[0] ?? version
 const best=currentBest(blend)
 const previous=version ? blend.versions.find(item=>item.number===version.number-1) : undefined
 const diffs=previous?versionDiff(previous,version):[]
 const rating=version?avgRating(version):0
 const profile=version?avgTaste(version.experiments):mkTaste(0)
 const allExperiments=blend.versions.flatMap(item=>item.experiments).sort((a,b)=>+new Date(b.date)-+new Date(a.date))
 const latestExperiment=version?.experiments.at(-1)
 const recommendation=latestExperiment ? recommend(latestExperiment,version,previous,db.pantry) : null
 const ratingDelta=previous ? rating-avgRating(previous) : null
 const timeline=blend.versions.map(item=>({id:item.id,number:item.number,rating:avgRating(item),best:item.id===best?.id,change:item.number===1?'Original':versionDiff(blend.versions.find(previousVersion=>previousVersion.number===item.number-1)!,item)[0]?.name||'Recipe adjustment'}))
 function markBest(){update({...db,blends:db.blends.map(item=>item.id===blend.id?{...item,versions:item.versions.map(candidate=>({...candidate,isBest:candidate.id===version.id}))}:item)});toast(`v${version.number} marked as your best version.`)}
 function toggleFavorite(){update({...db,blends:db.blends.map(item=>item.id===blend.id?{...item,favorite:!item.favorite}:item)})}
 return <div className="space-y-12 fade-up">
  <button className="btn-ghost px-0" onClick={()=>go('/blends')}><ArrowLeft size={16}/> Back to archive</button>
  <header className="border-b border-line pb-10"><div className="flex flex-col justify-between gap-8 xl:flex-row xl:items-end"><div className="max-w-3xl"><div className="small-label">{blend.category} / Personal recipe history</div><div className="mt-4 flex items-start gap-4"><span className="text-4xl sm:text-5xl">{blend.emoji}</span><div><h1 className="serif text-5xl leading-[1.05] sm:text-6xl">{blend.name}</h1><p className="mt-4 max-w-2xl text-sm leading-6 text-soft">{blend.description}</p></div></div></div><div className="flex flex-wrap gap-2"><button className="btn-primary" onClick={()=>setModal({type:'experiment',blendId:blend.id})}><Beaker size={16}/> Make Again</button><button className="btn-secondary" onClick={()=>setModal({type:'variation',blendId:blend.id})}><GitCompare size={16}/> Create Variation</button><button className="btn-secondary" disabled title="Editing is not connected in Demo Mode"><Settings size={16}/> Edit</button><button className="btn-ghost" onClick={toggleFavorite}><Heart size={16} fill={blend.favorite?'currentColor':'none'} className={blend.favorite?'text-rose':''}/> {blend.favorite?'Favorited':'Favorite'}</button></div></div><div className="mt-9 grid max-w-3xl gap-5 border-t border-line pt-5 sm:grid-cols-4"><div><div className="small-label">Current version</div><div className="mt-1 font-semibold">v{current?.number||'—'} · {current?.name||'—'}</div></div><div><div className="small-label">Current rating</div><div className="mt-1 serif text-3xl">{current&&avgRating(current)?avgRating(current).toFixed(1):'—'}<span className="ml-1 text-sm font-sans text-soft">/10</span></div></div><div><div className="small-label">Best version</div><div className="mt-1 font-semibold">v{best?.number||'—'} · {best?.name||'—'}</div></div><div><div className="small-label">Favorite</div><div className="mt-1 font-semibold">{blend.favorite?'In your favorites':'Not favorited'}</div></div></div></header>

  <section><div className="flex flex-col justify-between gap-3 border-b border-line pb-5 sm:flex-row sm:items-end"><div><div className="small-label">Blend evolution</div><h2 className="serif mt-2 text-4xl font-semibold">This drink has evolved over time.</h2></div><div className="text-sm text-soft">Select a version to inspect the evidence.</div></div><div className="mt-8 hidden overflow-x-auto pb-4 md:block"><div className="relative flex min-w-[760px] items-start justify-between px-5"><div className="absolute left-8 right-8 top-7 h-px bg-line"/>{timeline.map(item=><div key={item.id} className="relative z-10 flex min-w-[120px] flex-1 flex-col items-center"><button onClick={()=>setSelected(item.id)} className={`grid h-14 w-14 place-items-center rounded-full border-4 transition ${selected===item.id?'border-caramel bg-espresso text-paper shadow-soft':'border-cream bg-paper text-espresso shadow-sheet hover:border-caramel'}`} aria-label={`Select version ${item.number}`}><span className="text-xs font-semibold">V{item.number}</span></button><div className="mt-3 text-center"><div className="serif text-2xl">{item.rating?item.rating.toFixed(1):'—'}</div><div className="mt-1 text-xs font-semibold">{item.best?'Current best':item.change}</div><div className="mt-1 text-[11px] text-soft">{fmtDate(blend.versions.find(versionItem=>versionItem.id===item.id)?.createdAt||blend.createdAt)}</div></div></div>)}</div></div><div className="mt-8 space-y-0 border-l border-line pl-6 md:hidden">{timeline.map(item=><div key={item.id} className="relative pb-8 last:pb-0"><span className={`absolute -left-[31px] top-1 grid h-3 w-3 rounded-full border-2 border-cream ${selected===item.id?'bg-caramel':'bg-line'}`}/><button onClick={()=>setSelected(item.id)} className={`w-full border-b border-line pb-5 text-left ${selected===item.id?'text-espresso':'text-soft'}`}><div className="flex items-baseline justify-between gap-4"><span className="font-semibold">V{item.number} · {item.best?'Current best':item.change}</span><span className="serif text-2xl">{item.rating?item.rating.toFixed(1):'—'}</span></div><div className="mt-1 text-xs text-soft">{fmtDate(blend.versions.find(versionItem=>versionItem.id===item.id)?.createdAt||blend.createdAt)}</div></button></div>)}</div></section>

  <section className="grid gap-10 xl:grid-cols-[1.15fr_.85fr]"><div><div className="flex items-end justify-between gap-4 border-b border-line pb-4"><div><div className="small-label">Selected version</div><h2 className="serif mt-2 text-3xl font-semibold">v{version.number} · {version.name}</h2></div><div className="flex gap-2"><button className="btn-secondary" onClick={()=>setModal({type:'compare',blendId:blend.id})}><GitCompare size={16}/> Compare</button>{version.id!==best?.id&&<button className="btn-ghost text-green" onClick={markBest}><Star size={16}/> Mark best</button>}</div></div><div className="mt-6 grid gap-8 lg:grid-cols-[1fr_.85fr]"><div><div className="small-label">Recipe</div><div className="mt-4 divide-y divide-line border-y border-line">{version.ingredients.map(ingredient=><div key={ingredient.id} className="flex items-center justify-between gap-4 py-4 text-sm"><div><div className="font-semibold">{ingredient.name}</div><div className="mt-1 text-xs text-soft">{ingredient.brand||'House ingredient'}</div></div><div className="font-semibold">{ingredient.amount}{ingredient.unit}</div></div>)}</div><div className="mt-6"><div className="small-label">Preparation</div><p className="mt-2 text-sm leading-6 text-soft">{version.preparation}</p></div></div><div><div className="small-label">Version result</div><div className="mt-4 border-l-2 border-caramel bg-subtle p-5"><div className="serif text-5xl">{rating?rating.toFixed(1):'—'}<span className="ml-1 text-sm font-sans text-soft">/10</span></div><div className="mt-2 text-xs text-soft">{version.experiments.length} experiment{version.experiments.length!==1?'s':''} recorded</div>{version.notes&&<p className="mt-5 text-sm leading-6 text-soft">{version.notes}</p>}</div></div></div></div><div><div className="small-label">Taste profile</div><div className="mt-5 h-[280px]"><ResponsiveContainer width="100%" height="100%"><RadarChart data={tasteLabels.slice(0,6).map(([key,label])=>({subject:label,value:Number((profile as any)[key]||0)}))} outerRadius="68%"><PolarGrid stroke="#DDD2C3"/><PolarAngleAxis dataKey="subject" tick={{fontSize:10,fill:'#74665B'}}/><PolarRadiusAxis domain={[0,10]} tick={false} axisLine={false}/><Radar name="Taste" dataKey="value" stroke="#5D6B52" fill="#C5CEB8" fillOpacity={0.48}/></RadarChart></ResponsiveContainer></div><div className="grid grid-cols-2 gap-x-5 gap-y-3 border-t border-line pt-4">{(['sweetness','strength','creaminess','richness'] as const).map(key=><ProgressMetric key={key} label={key} value={(profile as any)[key]||0}/>)}</div></div></section>

  <section className="grid gap-10 border-t border-line pt-10 xl:grid-cols-[.95fr_1.05fr]"><div><div className="small-label">What changed?</div><h2 className="serif mt-2 text-3xl font-semibold">The useful differences</h2>{previous?<div className="mt-6 space-y-3">{diffs.map(diff=><div key={diff.name} className="border-l-2 border-caramel bg-subtle px-4 py-3"><div className="font-semibold">{diff.name}</div><div className="mt-2 flex flex-wrap items-center gap-2 text-sm"><span className="text-soft">{diff.from}</span><ArrowRight size={14} className="text-soft"/><span className="font-semibold">{diff.to}</span>{diff.delta!==null&&<span className="ml-auto font-semibold text-caramel">{diff.delta>=0?'+':''}{diff.delta} {diff.delta>=0?'increase':'decrease'}</span>}</div></div>)}{ratingDelta!==null&&<div className="border-l-2 border-green bg-sage/30 px-4 py-3"><div className="font-semibold">Overall rating</div><div className="mt-2 flex items-center gap-2 text-sm"><span>{avgRating(previous).toFixed(1)}</span><ArrowRight size={14}/><span className="font-semibold">{rating.toFixed(1)}</span><span className="ml-auto font-semibold text-green">{ratingDelta>=0?'+':''}{ratingDelta.toFixed(1)} rating change</span></div></div>}</div>:<p className="mt-6 text-sm leading-6 text-soft">This is the first recorded version. Future changes will appear here as clear, measurable differences.</p>}</div><div><div className="small-label">Version context</div><h2 className="serif mt-2 text-3xl font-semibold">Why this pour matters</h2><p className="mt-5 max-w-lg text-sm leading-7 text-soft">MyBlend keeps the previous recipe visible so each experiment stays grounded in what changed, what you noticed, and what you want to try next.</p><div className="mt-6 border-t border-line pt-5 text-sm"><div className="flex justify-between gap-4"><span className="text-soft">Created</span><span className="font-semibold">{fmtDate(version.createdAt)}</span></div><div className="mt-3 flex justify-between gap-4"><span className="text-soft">Experiments on version</span><span className="font-semibold">{version.experiments.length}</span></div></div></div></section>

  <section className="grid gap-10 border-t border-line pt-10 xl:grid-cols-[1fr_.9fr]"><div><div className="small-label">Experiment notes</div><h2 className="serif mt-2 text-3xl font-semibold">What you noticed</h2><div className="mt-5 divide-y divide-line">{allExperiments.length?allExperiments.map(experiment=><button key={experiment.id} onClick={()=>setSelected(blend.versions.find(item=>item.experiments.some(candidate=>candidate.id===experiment.id))?.id||selected)} className="group block w-full py-5 text-left first:pt-0"><div className="flex items-baseline justify-between gap-4"><div className="font-semibold group-hover:text-green">v{blend.versions.find(item=>item.experiments.some(candidate=>candidate.id===experiment.id))?.number||'—'} · {fmtDate(experiment.date)}</div><div className="serif text-2xl">{experiment.rating.toFixed(1)}<span className="ml-1 text-xs font-sans text-soft">/10</span></div></div><p className="mt-2 text-sm leading-6 text-soft">{experiment.notes||'No note recorded for this experiment.'}</p></button>):<p className="mt-5 text-sm leading-6 text-soft">No experiment notes yet. Make this version and record what you notice.</p>}</div></div><div className="surface-highlight p-6 sm:p-7"><div className="small-label !text-caramel-soft">Next experiment</div><h2 className="serif mt-2 text-3xl font-semibold">Keep the thread going</h2>{recommendation?<><p className="mt-5 text-sm leading-6 text-paper/75">{recommendation.summary}</p><div className="mt-6 border-t border-paper/15 pt-5"><div className="text-xs font-semibold uppercase tracking-[.12em] text-paper/60">Suggested direction</div><p className="mt-2 text-sm leading-6 text-paper">{recommendation.experimentIdea}</p>{recommendation.suggestions[1]&&<p className="mt-3 text-sm leading-6 text-paper/70">{recommendation.suggestions[1]}</p>}</div><button className="mt-7 rounded-lg bg-caramel-soft px-4 py-3 text-sm font-semibold text-espresso" onClick={()=>setModal({type:'experiment',blendId:blend.id})}><Beaker size={16}/> Make this experiment</button></>:<><p className="mt-5 text-sm leading-6 text-paper/75">Record an experiment on this version and MyBlend will suggest the next focused step using your existing taste data.</p><button className="mt-7 rounded-lg bg-caramel-soft px-4 py-3 text-sm font-semibold text-espresso" onClick={()=>setModal({type:'experiment',blendId:blend.id})}><Beaker size={16}/> Start first experiment</button></>}</div></section>
 </div>
}

function ProgressMetric({label,value}:{label:string;value:number}){return <div><div className="mb-1 flex justify-between text-xs font-extrabold"><span>{label}</span><span>{Number(value||0).toFixed(1)}</span></div><div className="h-2 overflow-hidden rounded-full bg-sage/30"><motion.div initial={{width:0}} animate={{width:`${Math.min(100,Number(value||0)*10)}%`}} className="h-full rounded-full bg-green"/></div></div>}

function ExperimentsPage({db,go}:{db:DB;go:(p:string)=>void}){
 const ex=flattenExperiments(db.blends).sort((a,b)=>+new Date(b.date)-+new Date(a.date))
 return <div className="space-y-6 fade-up"><div><div className="small-label">Experiment log</div><h1 className="serif mt-1 text-4xl font-semibold">Experiments</h1><p className="mt-2 text-sm leading-6 text-soft">A record of what you made, how it tasted, and what you learned from the result.</p></div>{ex.length===0?<EmptyState icon={FlaskConical} title="No experiments yet." description="Make a blend and record the first test."/>:<div className="grid gap-4 lg:grid-cols-2">{ex.map(e=><motion.div whileHover={{y:-2}} key={e.id} className="card p-5"><div className="flex items-start gap-4"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-cream text-2xl">{e.blend.emoji}</div><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-3"><div><div className="font-extrabold">{e.blend.name}</div><div className="mt-1 text-xs text-soft">v{e.version.number} · {fmtDate(e.date)}</div></div><div className="rounded-xl bg-sage px-2.5 py-1.5 text-sm font-extrabold text-green">{e.rating.toFixed(1)}</div></div><p className="mt-4 text-sm leading-6 text-soft">{e.notes||'No note recorded.'}</p><div className="mt-4 grid grid-cols-4 gap-2">{['sweetness','strength','creaminess','bitterness'].map(k=><div key={k} className="rounded-2xl bg-cream p-3"><div className="text-[10px] font-extrabold uppercase tracking-wide text-soft">{k.slice(0,6)}</div><div className="mt-1 font-extrabold">{(e.taste as any)[k]}</div></div>)}</div><div className="mt-4 flex items-center justify-between"><div className="text-xs font-semibold text-soft">{e.recommendation||'Recommendation generated from experiment data.'}</div><button className="btn-ghost" onClick={()=>go(`/blends/${e.blend.id}`)}>Open <ArrowRight size={15}/></button></div></div></div></motion.div>)}</div>}</div>
}

function LegacyPantryPage({db,setModal,update}:{db:DB;setModal:(m:Modal)=>void;update:(d:DB)=>void}){
 const low=db.pantry.filter(p=>p.quantity<=p.threshold)
 return <div className="space-y-6 fade-up"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="small-label">Ingredient shelf</div><h1 className="serif mt-1 text-4xl font-semibold">Pantry</h1><p className="mt-2 text-sm leading-6 text-soft">Know what you have before you decide what to make.</p></div><button className="btn-primary" onClick={()=>setModal({type:'pantry',blendId:''})}><Plus size={18}/> Add ingredient</button></div>{low.length>0&&<div className="rounded-3xl border border-caramel/30 bg-caramel-soft/20 p-5"><div className="flex gap-3"><div className="grid h-10 w-10 place-items-center rounded-2xl bg-caramel-soft"><Bell size={18}/></div><div><div className="font-extrabold">A few items are running low.</div><div className="mt-1 text-sm text-soft">{low.map(x=>x.name).join(', ')}</div></div></div></div>}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{db.pantry.map(p=><div key={p.id} className="card p-5"><div className="flex items-start justify-between gap-3"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-cream"><Package size={20} className="text-green"/></div><button className="btn-ghost p-2 text-rose" onClick={()=>update({...db,pantry:db.pantry.filter(x=>x.id!==p.id)})}><Trash2 size={16}/></button></div><div className="mt-4 font-extrabold">{p.name}</div><div className="mt-1 serif text-3xl font-semibold">{p.quantity}<span className="ml-1 text-base text-soft">{p.unit}</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-cream"><div className={`h-full rounded-full ${p.quantity<=p.threshold?'bg-rose':'bg-green'}`} style={{width:`${Math.min(100,(p.quantity/Math.max(p.quantity,p.threshold*3))*100)}%`}}/></div><div className="mt-2 flex items-center justify-between text-xs font-bold text-soft"><span>Low stock at {p.threshold}{p.unit}</span>{p.expiry&&<span>Expires {fmtDate(p.expiry)}</span>}</div></div>)}</div>{db.pantry.length===0&&<EmptyState icon={Package} title="Your pantry is empty." description="Add a few ingredients so recommendations can stay practical." action="Add Ingredient" onClick={()=>setModal({type:'pantry',blendId:''})}/>}</div>
}

function PantryPage({db,setModal,update}:{db:DB;setModal:(m:Modal)=>void;update:(d:DB)=>void}){
 const now=Date.now()
 const soon=now+7*86400000
 const lowStock=db.pantry.filter(item=>item.quantity<=item.threshold)
 const expiringSoon=db.pantry.filter(item=>item.quantity>item.threshold&&item.expiry&&+new Date(item.expiry)<=soon&&+new Date(item.expiry)>=now)
 const available=db.pantry.filter(item=>!lowStock.includes(item)&&!expiringSoon.includes(item))
 const pantryMatches=(blend:Blend)=>{const version=currentBest(blend);const missing=version.ingredients.filter(ingredient=>{const item=db.pantry.find(candidate=>candidate.name.toLowerCase()===ingredient.name.toLowerCase());return !item||item.unit!==ingredient.unit||item.quantity<ingredient.amount});return {blend,version,missing}}
 const ready= db.blends.map(pantryMatches).filter(item=>item.missing.length===0)
 const nearMatches=db.blends.map(pantryMatches).filter(item=>item.missing.length>0&&item.missing.length<=2).slice(0,3)
 return <div className="space-y-12 fade-up">
  <header className="flex flex-col justify-between gap-6 border-b border-line pb-8 lg:flex-row lg:items-end"><div><div className="small-label">Ingredient shelf</div><h1 className="serif mt-2 text-5xl font-semibold">Pantry</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-soft">A useful view of what is ready, what needs attention, and what your next drink can use.</p></div><button className="btn-primary self-start lg:self-auto" onClick={()=>setModal({type:'pantry',blendId:''})}><Plus size={17}/> Add Ingredient</button></header>
  <section><div className="flex items-end justify-between gap-4 border-b border-line pb-4"><div><div className="small-label">Use what I have</div><h2 className="serif mt-2 text-4xl font-semibold">Drinks within reach</h2></div><span className="text-sm text-soft">{ready.length} ready to make</span></div>{ready.length?<div className="mt-6 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{ready.map(({blend,version})=><button key={blend.id} onClick={()=>setModal({type:'experiment',blendId:blend.id})} className="group border-l-2 border-green bg-sage/20 p-5 text-left transition hover:bg-sage/30"><div className="flex items-start justify-between gap-4"><div><div className="small-label">{blend.category}</div><h3 className="serif mt-2 text-2xl font-semibold">{blend.name}</h3></div><span className="text-2xl">{blend.emoji}</span></div><div className="mt-5 flex items-center justify-between text-xs"><span className="text-soft">v{version.number} · {version.name}</span><span className="font-semibold text-green">Make again <ArrowRight size={14} className="inline"/></span></div></button>)}</div>:<div className="mt-6 border-l-2 border-caramel bg-caramel-soft/20 px-5 py-5"><div className="font-semibold">Nothing is fully matched yet.</div><p className="mt-2 max-w-xl text-sm leading-6 text-soft">Add or update an ingredient to unlock a ready-to-make blend. These are the closest matches right now.</p>{nearMatches.length>0&&<div className="mt-4 flex flex-wrap gap-x-6 gap-y-2 text-sm">{nearMatches.map(({blend,missing})=><button key={blend.id} onClick={()=>setModal({type:'experiment',blendId:blend.id})} className="font-semibold text-green">{blend.name}<span className="ml-2 text-xs font-normal text-soft">needs {missing.map(item=>item.name).join(', ')}</span></button>)}</div>}</div>}</section>
  <section><div className="border-b border-line pb-4"><div className="small-label">Your ingredients</div><h2 className="serif mt-2 text-4xl font-semibold">Keep the shelf honest</h2></div><PantryGroup title="Available" items={available} empty="Nothing is comfortably stocked yet." db={db} setModal={setModal} update={update}/><PantryGroup title="Low stock" items={lowStock} empty="No low-stock ingredients." db={db} setModal={setModal} update={update}/><PantryGroup title="Expiring soon" items={expiringSoon} empty="Nothing expires within the next seven days." db={db} setModal={setModal} update={update}/></section>
 </div>
}

function PantryGroup({title,items,empty,db,setModal,update}:{title:string;items:PantryItem[];empty:string;db:DB;setModal:(m:Modal)=>void;update:(d:DB)=>void}){
 return <div className="mt-8"><div className="flex items-baseline justify-between gap-4"><h3 className="text-sm font-semibold">{title}</h3><span className="text-xs text-soft">{items.length} item{items.length===1?'':'s'}</span></div>{items.length?<div className="mt-3 divide-y divide-line border-y border-line">{items.map(item=><PantryItemRow key={item.id} item={item} db={db} setModal={setModal} update={update}/>)}</div>:<div className="mt-3 border-y border-line py-5 text-sm text-soft">{empty}</div>}</div>
}

function PantryItemRow({item,db,setModal,update}:{item:PantryItem;db:DB;setModal:(m:Modal)=>void;update:(d:DB)=>void}){
 const low=item.quantity<=item.threshold
 const expiring=Boolean(item.expiry&&+new Date(item.expiry)<=Date.now()+7*86400000&&+new Date(item.expiry)>=Date.now())
 return <div className="flex flex-col gap-4 py-4 sm:flex-row sm:items-center sm:gap-6"><div className="min-w-0 flex-1"><div className="flex items-center gap-3"><span className={`h-2 w-2 rounded-full ${low?'bg-rose':expiring?'bg-caramel':'bg-green'}`}/><span className="font-semibold">{item.name}</span><span className="text-xs text-soft">{low?'Low stock':expiring?'Expiring soon':'Available'}</span></div>{item.expiry&&<div className="mt-1 pl-5 text-xs text-soft">Expires {fmtDate(item.expiry)}</div>}</div><label className="flex items-center gap-2 text-xs text-soft">Quantity<input aria-label={`Quantity of ${item.name}`} type="number" min="0" value={item.quantity} onChange={event=>update({...db,pantry:db.pantry.map(candidate=>candidate.id===item.id?{...candidate,quantity:Number(event.target.value)}:candidate)})} className="ds-control w-24 py-2 text-sm font-semibold"/><span>{item.unit}</span></label><div className="flex items-center gap-1"><button className="btn-ghost px-2 text-xs" onClick={()=>setModal({type:'pantry',blendId:'',pantryId:item.id})}><Settings size={14}/> Edit</button><button className="btn-ghost px-2 text-xs text-rose" onClick={()=>update({...db,pantry:db.pantry.filter(candidate=>candidate.id!==item.id)})}><Trash2 size={14}/> Remove</button></div></div>
}

function InsightsPage({db}:{db:DB}){
 const ex=flattenExperiments(db.blends).sort((a,b)=>+new Date(a.date)-+new Date(b.date));
 const avg=ex.length?ex.reduce((s,e)=>s+e.rating,0)/ex.length:0
 const byCat=allCategories.map(cat=>{const xs=ex.filter(e=>e.blend.category===cat);return{name:cat.split(' ')[0],rating:xs.length?xs.reduce((s,e)=>s+e.rating,0)/xs.length:0,tests:xs.length}}).filter(x=>x.tests)
 const time=ex.map(e=>({date:new Date(e.date).toLocaleDateString('en-US',{month:'short',day:'numeric'}),rating:e.rating}))
 const taste=avgTaste(ex as never)
 const most=([...db.blends].sort((a,b)=>b.versions.flatMap(v=>v.experiments).length-a.versions.flatMap(v=>v.experiments).length)[0])
 return <div className="space-y-6 fade-up"><div><div className="small-label">Personal analytics</div><h1 className="serif mt-1 text-4xl font-semibold">Insights</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-soft">Patterns from your own ratings—not generic recipe opinions.</p></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat icon={Coffee} label="Average Rating" value={avg?avg.toFixed(1):'—'} note="all recorded tests"/><Stat icon={FlaskConical} label="Total Experiments" value={String(ex.length)} note="across all blends"/><Stat icon={TrendingUp} label="Biggest Improvement" value={improvement(db.blends)} note="version-to-version"/><Stat icon={History} label="Most Experimented" value={most?`${most.versions.length} v`: '—'} note={most?.name??'—'}/></div><div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><div className="card p-5 sm:p-7"><div className="small-label">Rating over time</div><h2 className="serif mt-1 text-2xl font-semibold">Does experimentation move the needle?</h2><div className="mt-5 h-[280px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={time}><defs><linearGradient id="ratingFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#AAB89A" stopOpacity=".7"/><stop offset="100%" stopColor="#AAB89A" stopOpacity=".05"/></linearGradient></defs><CartesianGrid stroke="#E8DED0" vertical={false}/><XAxis dataKey="date" tick={{fontSize:10,fill:'#725C4D'}} tickLine={false}/><YAxis domain={[0,10]} tick={{fontSize:10,fill:'#725C4D'}} tickLine={false} axisLine={false}/><Tooltip contentStyle={{borderRadius:16,border:'1px solid #E8DED0',background:'#FFFDF9'}}/><Area type="monotone" dataKey="rating" stroke="#526446" fill="url(#ratingFill)" strokeWidth={3}/></AreaChart></ResponsiveContainer></div></div><div className="card p-5 sm:p-7"><div className="small-label">Taste profile</div><h2 className="serif mt-1 text-2xl font-semibold">What you tend to like</h2><div className="mt-5 h-[300px]"><ResponsiveContainer width="100%" height="100%"><RadarChart data={tasteLabels.slice(0,6).map(([k,l])=>({subject:l,value:Number((taste as any)[k]||0)}))}><PolarGrid stroke="#E8DED0"/><PolarAngleAxis dataKey="subject" tick={{fontSize:10,fill:'#725C4D'}}/><PolarRadiusAxis domain={[0,10]} tick={false} axisLine={false}/><Radar dataKey="value" stroke="#C9945A" fill="#E6C08B" fillOpacity={0.5}/></RadarChart></ResponsiveContainer></div></div></div><div className="grid gap-5 xl:grid-cols-[1fr_.8fr]"><div className="card p-5 sm:p-7"><div className="small-label">Average rating by category</div><h2 className="serif mt-1 text-2xl font-semibold">Where your best patterns live</h2><div className="mt-5 h-[270px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={byCat}><CartesianGrid stroke="#E8DED0" vertical={false}/><XAxis dataKey="name" tick={{fontSize:10,fill:'#725C4D'}} tickLine={false}/><YAxis domain={[0,10]} tick={{fontSize:10,fill:'#725C4D'}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{borderRadius:16,border:'1px solid #E8DED0',background:'#FFFDF9'}}/><Bar dataKey="rating" fill="#526446" radius={[10,10,0,0]}/></BarChart></ResponsiveContainer></div></div><div className="card bg-espresso p-6 text-paper sm:p-7"><div className="small-label !text-caramel-soft">Taste tendencies</div><h2 className="serif mt-1 text-3xl font-semibold">Signals from your own notes.</h2><div className="mt-5 space-y-3">{tasteInsights(ex).map((x,i)=><div key={i} className="rounded-2xl bg-paper/10 p-4 text-sm leading-6 text-paper/80">{x}</div>)}</div></div></div></div>
}

function improvement(blends:Blend[]){let bestDelta=0;for(const b of blends)for(let i=1;i<b.versions.length;i++){const a=avgRating(b.versions[i-1]),c=avgRating(b.versions[i]);bestDelta=Math.max(bestDelta,c-a)}return bestDelta?`+${bestDelta.toFixed(1)}`:'—'}
function tasteInsights(ex:any[]){ if(ex.length<3)return ['Keep experimenting. Personalized tendencies become more meaningful after a few more tests.']; const out:string[]=[]; const creamy=ex.filter(e=>e.taste.creaminess>=8); if(creamy.length>=2)out.push(`You tend to rate creamy drinks higher: ${avg(creamy.map(x=>x.rating)).toFixed(1)}/10 average when creaminess is 8+.`); const sweet=ex.filter(e=>e.taste.sweetness>=8); if(sweet.length>=2)out.push(`High-sweetness drinks currently average ${avg(sweet.map(x=>x.rating)).toFixed(1)}/10.`); const bitter=ex.filter(e=>e.taste.bitterness>=7); if(bitter.length>=2)out.push(`Bitter drinks average ${avg(bitter.map(x=>x.rating)).toFixed(1)}/10 in your history.`); return out.length?out:['Your ratings are still varied—there is not enough evidence for a stable taste tendency yet.']}
function avg(a:number[]){return a.length?a.reduce((x,y)=>x+y,0)/a.length:0}

function SettingsPage({db,update,toast}:{db:DB;update:(d:DB)=>void;toast:(s:string)=>void}){return <div className="mx-auto max-w-3xl space-y-6 fade-up"><div><div className="small-label">Preferences</div><h1 className="serif mt-1 text-4xl font-semibold">Settings</h1><p className="mt-2 text-sm text-soft">Your prototype is intentionally usable without a server. Supabase can be connected later.</p></div><div className="card p-6"><div className="small-label">Profile</div><div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="block text-sm font-bold">Display name<input className="mt-2 w-full rounded-2xl border border-line bg-cream px-4 py-3" value={db.name} onChange={e=>update({...db,name:e.target.value})}/></label><div><div className="text-sm font-bold">Mode</div><div className="mt-2 rounded-2xl bg-cream p-4 text-sm text-soft"><span className="font-extrabold text-espresso">Demo Mode</span><br/>Data is stored locally so the app still works without Supabase credentials.</div></div></div></div><div className="card p-6"><div className="small-label">Taste profile</div><div className="mt-5 grid gap-4 sm:grid-cols-2">{(['sweetness','strength','creaminess','richness','refreshing','bitterness'] as const).map(k=><label key={k} className="block text-sm font-bold"><div className="flex justify-between"><span>{k}</span><span>{(db.tasteProfile as any)[k]?.toFixed?.(1)??0}</span></div><input type="range" min="0" max="10" step=".1" value={(db.tasteProfile as any)[k]??0} onChange={e=>update({...db,tasteProfile:{...db.tasteProfile,[k]:Number(e.target.value)}})} className="mt-2 w-full"/></label>)}</div></div><div className="card border-rose/20 bg-rose/5 p-6"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-2xl bg-paper"><Database size={18}/></div><div><div className="font-extrabold">Reset demo data</div><p className="mt-1 text-sm text-soft">Restore the curated sample blends, experiments, pantry items and taste history.</p><button className="btn-secondary mt-4" onClick={()=>{const fresh=seedDB();update(fresh);toast('Demo data restored.')}}><RefreshCw size={16}/> Restore demo</button></div></div></div></div>}

function EmptyState({icon:Icon=Beaker,title,description,action,onClick}:{icon?:any;title:string;description:string;action?:string;onClick?:()=>void}){return <div className="card p-10 text-center"><div className="mx-auto grid h-16 w-16 place-items-center rounded-3xl bg-cream"><Icon size={25} className="text-green"/></div><h3 className="serif mt-5 text-2xl font-semibold">{title}</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-soft">{description}</p>{action&&<button className="btn-primary mt-5" onClick={onClick}>{action}</button>}</div>}

function ModalHost({modal,db,update,close,toast}:{modal:Modal;db:DB;update:(d:DB)=>void;close:()=>void;toast:(s:string)=>void}){
 useEffect(()=>{if(!modal)return;const handleKeyDown=(event:KeyboardEvent)=>{if(event.key==='Escape')close()};window.addEventListener('keydown',handleKeyDown);return()=>window.removeEventListener('keydown',handleKeyDown)},[modal,close])
 return <AnimatePresence>{modal&&<motion.div className="fixed inset-0 z-[60] flex items-end justify-center bg-espresso/30 p-0 sm:items-center sm:p-6" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onClick={close}><motion.div className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-t-[30px] bg-paper p-5 shadow-float sm:rounded-[30px] sm:p-7" initial={{y:40,opacity:0}} animate={{y:0,opacity:1}} exit={{y:20,opacity:0}} onClick={e=>e.stopPropagation()}>{modal.type==='create'&&<CreateBlendModal db={db} update={update} close={close} toast={toast}/>} {modal.type==='experiment'&&<ExperimentModal db={db} update={update} close={close} blendId={modal.blendId} toast={toast}/>} {modal.type==='variation'&&<VariationModal db={db} update={update} close={close} blendId={modal.blendId} toast={toast}/>} {modal.type==='pantry'&&<PantryEditModal db={db} update={update} close={close} pantryId={modal.pantryId}/>} {modal.type==='compare'&&<CompareModal db={db} close={close} blendId={modal.blendId}/>}</motion.div></motion.div>}</AnimatePresence>
}

function ModalHeader({eyebrow,title,close}:{eyebrow:string;title:string;close:()=>void}){return <div className="flex items-start justify-between gap-4"><div><div className="small-label">{eyebrow}</div><h2 className="serif mt-1 text-3xl font-semibold">{title}</h2></div><button className="btn-ghost p-2" onClick={close} aria-label={`Close ${title}`}><X size={19}/></button></div>}

function LegacyCreateBlendModal({db,update,close,toast}:{db:DB;update:(d:DB)=>void;close:()=>void;toast:(s:string)=>void}){
 const [step,setStep]=useState(1); const [name,setName]=useState(''); const [category,setCategory]=useState<Category>('Coffee'); const [description,setDescription]=useState(''); const [photo,setPhoto]=useState<string|null>(null); const [ingredients,setIngredients]=useState<Ingredient[]>([makeIngredient('',0,'ml')]); const [method,setMethod]=useState('Shake over ice'); const [temp,setTemp]=useState('Cold'); const [ice,setIce]=useState('Medium');
 function save(){ if(!name.trim()){toast('Give your blend a name first.');return} const clean=ingredients.filter(i=>i.name.trim()); const b:Blend={id:uid('blend'),name:name.trim(),category,emoji:categoryMeta[category].emoji,description:description||'A personal experiment waiting to evolve.',createdAt:new Date().toISOString(),favorite:false,versions:[{id:uid('v'),number:1,name:'Original',createdAt:new Date().toISOString(),notes:'First recorded version.',ingredients:clean.length?clean.map(i=>({...i,id:uid('ing')})):[],preparation:`${method}. ${temp}. Ice: ${ice}.`,experiments:[]} ]}; update({...db,blends:[b,...db.blends]}); close(); toast('Your first blend has been created.'); }
 return <div><ModalHeader eyebrow={`Create blend · Step ${step} of 4`} title="Build the recipe" close={close}/><div className="mt-6">{step===1&&<div><p className="text-sm text-soft">Choose the drink family so MyBlend can tailor the experiment profile.</p><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3">{allCategories.map(c=><button key={c} onClick={()=>setCategory(c)} className={`rounded-3xl border p-4 text-left ${category===c?'border-green bg-sage/30':'border-line bg-cream'}`}><div className="text-3xl">{categoryMeta[c].emoji}</div><div className="mt-3 font-extrabold">{c}</div><div className="mt-1 text-xs text-soft">Personal recipe log</div></button>)}</div></div>}{step===2&&<div className="space-y-4"><label className="block text-sm font-bold">Drink name<input value={name} onChange={e=>setName(e.target.value)} className="mt-2 w-full rounded-2xl border border-line bg-cream px-4 py-3" placeholder="Brown Sugar Oat Latte"/></label><label className="block text-sm font-bold">Description<textarea value={description} onChange={e=>setDescription(e.target.value)} rows={4} className="mt-2 w-full rounded-2xl border border-line bg-cream px-4 py-3" placeholder="What makes this blend worth remembering?"/></label><div className="rounded-3xl border border-dashed border-line bg-cream p-5"><div className="small-label">Photo</div><div className="mt-2 text-sm text-soft">In Supabase mode this can upload to Storage. Demo mode keeps the recipe text-first.</div>{photo&&<div className="mt-3 text-xs font-bold text-green">Photo selected: {photo}</div>}</div></div>}{step===3&&<div><div className="flex items-center justify-between"><div><div className="small-label">Ingredients</div><p className="mt-1 text-sm text-soft">Record exact measurements and brands so your best version is reproducible.</p></div><button className="btn-secondary" onClick={()=>setIngredients([...ingredients,makeIngredient('',0,'ml')])}><Plus size={16}/> Add row</button></div><div className="mt-5 space-y-3">{ingredients.map((i,idx)=><div key={idx} className="grid gap-2 sm:grid-cols-[1.5fr_1fr_.75fr_auto]"><input value={i.name} onChange={e=>setIngredients(ingredients.map((x,j)=>j===idx?{...x,name:e.target.value}:x))} placeholder="Ingredient" className="rounded-2xl border border-line bg-cream px-4 py-3 text-sm"/><input value={i.brand||''} onChange={e=>setIngredients(ingredients.map((x,j)=>j===idx?{...x,brand:e.target.value}:x))} placeholder="Brand" className="rounded-2xl border border-line bg-cream px-4 py-3 text-sm"/><input value={i.amount||''} onChange={e=>setIngredients(ingredients.map((x,j)=>j===idx?{...x,amount:Number(e.target.value)}:x))} type="number" placeholder="Amount" className="rounded-2xl border border-line bg-cream px-4 py-3 text-sm"/><input value={i.unit} onChange={e=>setIngredients(ingredients.map((x,j)=>j===idx?{...x,unit:e.target.value}:x))} placeholder="Unit" className="rounded-2xl border border-line bg-cream px-4 py-3 text-sm"/></div>)}</div></div>}{step===4&&<div className="space-y-4"><div className="grid gap-3 sm:grid-cols-2"><label className="block text-sm font-bold">Method<select value={method} onChange={e=>setMethod(e.target.value)} className="mt-2 w-full rounded-2xl border border-line bg-cream px-4 py-3"><option>Shake over ice</option><option>Stir over ice</option><option>Whisk then pour</option><option>Blend</option><option>Build in glass</option></select></label><label className="block text-sm font-bold">Temperature<select value={temp} onChange={e=>setTemp(e.target.value)} className="mt-2 w-full rounded-2xl border border-line bg-cream px-4 py-3"><option>Cold</option><option>Room temperature</option><option>Warm</option><option>Hot</option></select></label></div><div><div className="small-label">Ice level</div><div className="mt-2 grid grid-cols-3 gap-2">{['Light','Medium','Heavy'].map(x=><button key={x} onClick={()=>setIce(x)} className={`rounded-2xl border px-4 py-3 text-sm font-extrabold ${ice===x?'border-green bg-sage/30':'border-line bg-cream'}`}>{x}</button>)}</div></div><div className="rounded-3xl bg-cream p-5"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-2xl bg-paper"><Zap size={18} className="text-caramel"/></div><div><div className="font-extrabold">Version 1 will be created automatically.</div><div className="mt-1 text-sm leading-6 text-soft">You can experiment immediately without overwriting this baseline.</div></div></div></div></div>}</div><div className="mt-7 flex items-center justify-between border-t border-line pt-5"><button className="btn-ghost" onClick={()=>step>1?setStep(step-1):close()}>{step>1?'Back':'Cancel'}</button>{step<4?<button className="btn-primary" onClick={()=>setStep(step+1)}>Continue <ArrowRight size={16}/></button>:<button className="btn-primary" onClick={save}><Check size={16}/> Create Version 1</button>}</div></div>
}

function CreateBlendModal({db,update,close,toast}:{db:DB;update:(d:DB)=>void;close:()=>void;toast:(s:string)=>void}){
 const [step,setStep]=useState(1)
 const [name,setName]=useState('')
 const [category,setCategory]=useState<Category>('Coffee')
 const [description,setDescription]=useState('')
 const [photo,setPhoto]=useState<string|null>(null)
 const [ingredients,setIngredients]=useState<Ingredient[]>([makeIngredient('',0,'ml')])
 const [method,setMethod]=useState('Shake over ice')
 const [temperature,setTemperature]=useState('Cold')
 const [ice,setIce]=useState('Medium')
 const [servingSize,setServingSize]=useState('1 serving')
 const [prepTime,setPrepTime]=useState('5 minutes')
 const [errors,setErrors]=useState<Record<string,string>>({})

 function updateIngredient(index:number,patch:Partial<Ingredient>){setIngredients(current=>current.map((ingredient,itemIndex)=>itemIndex===index?{...ingredient,...patch}:ingredient))}
 function moveIngredient(index:number,direction:-1|1){const next=index+direction;if(next<0||next>=ingredients.length)return;const reordered=[...ingredients];[reordered[index],reordered[next]]=[reordered[next],reordered[index]];setIngredients(reordered)}
 function validateCurrentStep(){
  const nextErrors:Record<string,string>={}
  if(step===1&&!name.trim())nextErrors.name='Give this drink a name before moving on.'
  if(step===2){
   if(!ingredients.length||ingredients.some(ingredient=>!ingredient.name.trim()||ingredient.amount<=0))nextErrors.ingredients='Add a name and amount for every ingredient, or remove the empty row.'
  }
  if(step===3&&!method.trim())nextErrors.method='Describe how this drink comes together.'
  setErrors(nextErrors)
  return Object.keys(nextErrors).length===0
 }
 function nextStep(){if(validateCurrentStep())setStep(current=>Math.min(5,current+1))}
 function previousStep(){setErrors({});setStep(current=>Math.max(1,current-1))}
 function save(){
  if(!validateCurrentStep()&&step<5){return}
  const clean=ingredients.filter(ingredient=>ingredient.name.trim())
  if(!name.trim()||!clean.length){setStep(name.trim()?2:1);return}
  const preparation=`${method}. Temperature: ${temperature}. Ice: ${ice}. Serving size: ${servingSize}. Preparation time: ${prepTime}.`
  const blend:Blend={id:uid('blend'),name:name.trim(),category,emoji:categoryMeta[category].emoji,description:description||'A personal experiment waiting to evolve.',createdAt:new Date().toISOString(),favorite:false,versions:[{id:uid('v'),number:1,name:'Original',createdAt:new Date().toISOString(),notes:'First recorded version.',ingredients:clean.map(ingredient=>({...ingredient,id:uid('ing')})),preparation,experiments:[]} ]}
  update({...db,blends:[blend,...db.blends]});close();toast('Version 1 has been added to your Blend Lab.')
 }
 const stepData=[['01','Identity','Name the drink'],['02','Ingredients','Make it repeatable'],['03','Preparation','Describe the pour'],['04','Review','Check the recipe'],['05','Create','Record Version 1']]
 return <div>
  <div className="flex items-start justify-between gap-4"><div><div className="small-label">Create a new blend</div><h2 className="serif mt-2 text-4xl font-semibold">Set up the experiment</h2></div><button className="btn-ghost p-2" onClick={close} aria-label="Close create blend flow"><X size={19}/></button></div>
  <div className="mt-7 grid grid-cols-5 gap-1 border-y border-line py-4">{stepData.map(([number,label,helper],index)=><div key={number} className={`min-w-0 border-l-2 pl-2 sm:pl-3 ${index+1===step?'border-caramel text-espresso':'border-line text-soft'}`}><div className="text-[10px] font-semibold tracking-[.12em]">{number}</div><div className="mt-1 truncate text-xs font-semibold sm:text-sm">{label}</div><div className="mt-1 hidden truncate text-[10px] text-soft sm:block">{helper}</div></div>)}</div>
  <div className="mt-7 min-h-[360px]">
   {step===1&&<div className="space-y-6"><div><div className="small-label">Identity</div><p className="mt-2 max-w-lg text-sm leading-6 text-soft">Give the recipe a clear identity. You can refine the details as it evolves.</p></div><label className="block text-sm font-semibold">Drink name<input autoFocus value={name} onChange={event=>{setName(event.target.value);setErrors(current=>({...current,name:''}))}} className={`ds-control mt-2 w-full ${errors.name?'border-rose':''}`} placeholder="Iced Brown Sugar Oat Latte" aria-invalid={Boolean(errors.name)}/>{errors.name&&<span className="mt-2 block text-xs text-rose">{errors.name}</span>}</label><div><div className="text-sm font-semibold">Category</div><div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-3">{allCategories.map(item=><button type="button" key={item} onClick={()=>setCategory(item)} className={`border px-3 py-3 text-left text-sm transition ${category===item?'border-green bg-sage/30 font-semibold':'border-line bg-cream hover:border-caramel'}`}><span className="mr-2 text-lg">{categoryMeta[item].emoji}</span>{item}</button>)}</div></div><label className="block text-sm font-semibold">Description<span className="ml-2 text-xs font-normal text-soft">Optional</span><textarea value={description} onChange={event=>setDescription(event.target.value)} rows={3} className="ds-control mt-2 w-full" placeholder="What makes this drink worth remembering?"/></label><label className="block text-sm font-semibold">Photo<span className="ml-2 text-xs font-normal text-soft">Optional</span><input type="file" accept="image/*" onChange={event=>setPhoto(event.target.files?.[0]?.name||null)} className="ds-control mt-2 w-full text-sm"/>{photo&&<span className="mt-2 block text-xs text-green">Selected: {photo}</span>}</label></div>}
   {step===2&&<div><div className="flex items-start justify-between gap-4"><div><div className="small-label">Ingredients</div><p className="mt-2 max-w-lg text-sm leading-6 text-soft">Record exact measurements, brands, and preparation notes so Version 1 can be made again.</p></div><button type="button" className="btn-secondary shrink-0" onClick={()=>setIngredients(current=>[...current,makeIngredient('',0,'ml')])}><Plus size={16}/> Add row</button></div>{errors.ingredients&&<div className="mt-4 border-l-2 border-rose bg-rose/5 px-4 py-3 text-sm text-rose">{errors.ingredients}</div>}<div className="mt-5 space-y-3">{ingredients.map((ingredient,index)=><div key={ingredient.id} className="border-b border-line pb-4"><div className="grid gap-2 sm:grid-cols-[1fr_1fr_5rem_5rem_auto] sm:items-end"><label className="block text-xs font-semibold sm:col-span-2">Ingredient<input value={ingredient.name} onChange={event=>updateIngredient(index,{name:event.target.value})} className="ds-control mt-1 w-full" placeholder="Espresso"/></label><label className="block text-xs font-semibold">Brand<input value={ingredient.brand||''} onChange={event=>updateIngredient(index,{brand:event.target.value})} className="ds-control mt-1 w-full" placeholder="Optional"/></label><label className="block text-xs font-semibold">Amount<input type="number" min="0" value={ingredient.amount||''} onChange={event=>updateIngredient(index,{amount:Number(event.target.value)})} className="ds-control mt-1 w-full" placeholder="36"/></label><label className="block text-xs font-semibold">Unit<select value={ingredient.unit} onChange={event=>updateIngredient(index,{unit:event.target.value})} className="ds-control mt-1 w-full"><option>ml</option><option>g</option><option>oz</option><option>piece</option><option>dash</option></select></label><div className="flex items-center gap-1"><button type="button" className="btn-ghost p-2" onClick={()=>moveIngredient(index,-1)} disabled={index===0} aria-label="Move ingredient up">↑</button><button type="button" className="btn-ghost p-2" onClick={()=>moveIngredient(index,1)} disabled={index===ingredients.length-1} aria-label="Move ingredient down">↓</button><button type="button" className="btn-ghost p-2 text-rose" onClick={()=>setIngredients(current=>current.length===1?[makeIngredient('',0,'ml')]:current.filter((_,itemIndex)=>itemIndex!==index))} aria-label="Remove ingredient">×</button></div></div><label className="mt-2 block text-xs font-semibold">Preparation note<span className="ml-2 font-normal text-soft">Optional</span><input value={ingredient.prep||''} onChange={event=>updateIngredient(index,{prep:event.target.value})} className="ds-control mt-1 w-full" placeholder="Pull as a double shot, chilled, sifted…"/></label></div>)}</div></div>}
   {step===3&&<div className="space-y-6"><div><div className="small-label">Preparation</div><p className="mt-2 max-w-lg text-sm leading-6 text-soft">Capture the conditions that make this version taste like this version.</p></div><div className="grid gap-5 sm:grid-cols-2"><label className="block text-sm font-semibold sm:col-span-2">Method<input autoFocus value={method} onChange={event=>{setMethod(event.target.value);setErrors(current=>({...current,method:''}))}} className={`ds-control mt-2 w-full ${errors.method?'border-rose':''}`} placeholder="Shake over ice"/>{errors.method&&<span className="mt-2 block text-xs text-rose">{errors.method}</span>}</label><label className="block text-sm font-semibold">Temperature<select value={temperature} onChange={event=>setTemperature(event.target.value)} className="ds-control mt-2 w-full"><option>Cold</option><option>Room temperature</option><option>Warm</option><option>Hot</option></select></label><label className="block text-sm font-semibold">Ice<select value={ice} onChange={event=>setIce(event.target.value)} className="ds-control mt-2 w-full"><option>None</option><option>Light</option><option>Medium</option><option>Full</option><option>Crushed</option></select></label><label className="block text-sm font-semibold">Serving size<input value={servingSize} onChange={event=>setServingSize(event.target.value)} className="ds-control mt-2 w-full" placeholder="1 serving / 350ml"/></label><label className="block text-sm font-semibold">Preparation time<input value={prepTime} onChange={event=>setPrepTime(event.target.value)} className="ds-control mt-2 w-full" placeholder="5 minutes"/></label></div></div>}
   {step===4&&<div><div className="small-label">Review</div><p className="mt-2 text-sm leading-6 text-soft">Read the whole recipe once before it becomes Version 1.</p><div className="mt-6 border-y border-line py-6"><div className="flex items-start justify-between gap-4"><div><div className="text-xs font-semibold uppercase tracking-[.12em] text-soft">{category}</div><h3 className="serif mt-2 text-3xl font-semibold">{name||'Untitled blend'}</h3><p className="mt-2 max-w-xl text-sm leading-6 text-soft">{description||'No description added.'}</p></div><div className="text-4xl">{categoryMeta[category].emoji}</div></div><div className="mt-7 grid gap-8 lg:grid-cols-[1.1fr_.9fr]"><div><div className="small-label">Ingredients</div><div className="mt-3 divide-y divide-line">{ingredients.filter(ingredient=>ingredient.name.trim()).map(ingredient=><div key={ingredient.id} className="flex items-center justify-between gap-4 py-3 text-sm"><div><span className="font-semibold">{ingredient.name}</span>{ingredient.brand&&<span className="ml-2 text-xs text-soft">{ingredient.brand}</span>}{ingredient.prep&&<div className="mt-1 text-xs text-soft">{ingredient.prep}</div>}</div><span className="font-semibold">{ingredient.amount}{ingredient.unit}</span></div>)}</div></div><div><div className="small-label">Preparation</div><dl className="mt-3 space-y-3 text-sm"><div className="flex justify-between gap-4"><dt className="text-soft">Method</dt><dd className="font-semibold text-right">{method}</dd></div><div className="flex justify-between gap-4"><dt className="text-soft">Temperature</dt><dd className="font-semibold">{temperature}</dd></div><div className="flex justify-between gap-4"><dt className="text-soft">Ice</dt><dd className="font-semibold">{ice}</dd></div><div className="flex justify-between gap-4"><dt className="text-soft">Serving</dt><dd className="font-semibold">{servingSize}</dd></div><div className="flex justify-between gap-4"><dt className="text-soft">Time</dt><dd className="font-semibold">{prepTime}</dd></div></dl></div></div></div></div>}
   {step===5&&<div className="py-10 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-full bg-sage text-green"><Check size={24}/></div><div className="small-label mt-6">Create</div><h3 className="serif mt-2 text-4xl font-semibold">Ready to record Version 1?</h3><p className="mx-auto mt-3 max-w-md text-sm leading-6 text-soft">This is the first entry in {name||'your blend'}'s history. You can test it, compare it, and create variations whenever the next idea arrives.</p><button type="button" className="btn-primary mt-7" onClick={save}><Check size={17}/> Create Version 1</button></div>}
  </div>
  {step<5&&<div className="flex items-center justify-between border-t border-line pt-5"><button type="button" className="btn-ghost" onClick={previousStep} disabled={step===1}>Back</button><div className="text-xs text-soft">Step {step} of 5</div><button type="button" className="btn-primary" onClick={nextStep}>{step===4?'Continue to create':'Continue'} <ArrowRight size={16}/></button></div>}
  {step===5&&<button type="button" className="btn-ghost mt-4 w-full" onClick={previousStep}>Back to review</button>}
 </div>
}

function LegacyExperimentModal({db,update,close,blendId,toast}:{db:DB;update:(d:DB)=>void;close:()=>void;blendId:string;toast:(s:string)=>void}){
 const blend=db.blends.find(b=>b.id===blendId)!; const [versionId,setVersionId]=useState(currentBest(blend).id); const version=blend.versions.find(v=>v.id===versionId)!; const [rating,setRating]=useState(8); const [taste,setTaste]=useState<Taste>({...mkTaste(6)}); const [notes,setNotes]=useState('');
 function save(){const prior=version.experiments[version.experiments.length-1]; const exp:Experiment={id:uid('exp'),date:new Date().toISOString(),rating,taste,notes}; const prevV=blend.versions.find(v=>v.number===version.number-1); const rec=recommend(exp,version,prevV,db.pantry); exp.recommendation=rec.suggestions[0]; const next={...db,blends:db.blends.map(b=>b.id===blend.id?{...b,versions:b.versions.map(v=>v.id===version.id?{...v,experiments:[...v.experiments,exp]}:v)}:b)}; update({...next,tasteProfile:avgTaste([...flattenExperiments(next.blends)] as never)}); close(); toast('Experiment saved. Recommendation generated.'); }
 return <div><ModalHeader eyebrow="Experiment log" title={`Make again · ${blend.name}`} close={close}/><div className="mt-6 space-y-6"><label className="block text-sm font-bold">Version<select value={versionId} onChange={e=>setVersionId(e.target.value)} className="mt-2 w-full rounded-2xl border border-line bg-cream px-4 py-3">{blend.versions.map(v=><option key={v.id} value={v.id}>v{v.number} · {v.name}</option>)}</select></label><div className="rounded-3xl bg-cream p-5"><div className="flex items-end justify-between"><div><div className="small-label">Overall rating</div><div className="serif mt-1 text-5xl font-semibold">{rating.toFixed(1)}</div></div><div className="text-xs font-bold text-soft">0–10</div></div><input type="range" min="0" max="10" step=".1" value={rating} onChange={e=>setRating(Number(e.target.value))} className="mt-5 w-full"/></div><div><div className="small-label">Taste check-in</div><div className="mt-4 grid gap-4 sm:grid-cols-2">{tasteLabels.map(([k,label])=><label key={k} className="block text-sm font-bold"><div className="flex justify-between"><span>{label}</span><span>{(taste as any)[k].toFixed(0)}</span></div><input type="range" min="0" max="10" step="1" value={(taste as any)[k]} onChange={e=>setTaste({...taste,[k]:Number(e.target.value)})} className="mt-2 w-full"/></label>)}</div></div><label className="block text-sm font-bold">What did you notice?<textarea value={notes} onChange={e=>setNotes(e.target.value)} rows={4} className="mt-2 w-full rounded-2xl border border-line bg-cream px-4 py-3" placeholder="Too sweet, texture was perfect, matcha could be stronger…"/></label><div className="rounded-3xl border border-line p-5"><div className="flex items-start gap-3"><div className="grid h-10 w-10 place-items-center rounded-2xl bg-sage"><BrainCircuit size={18} className="text-green"/></div><div><div className="font-extrabold">Recommendation engine</div><div className="mt-1 text-sm leading-6 text-soft">A deterministic recommendation will be generated from this rating, taste profile, version history, and pantry.</div></div></div></div></div><div className="mt-7 flex justify-end gap-2 border-t border-line pt-5"><button className="btn-secondary" onClick={close}>Cancel</button><button className="btn-primary" onClick={save}><Check size={16}/> Save Experiment</button></div></div>
}

function ExperimentModal({db,update,close,blendId,toast}:{db:DB;update:(d:DB)=>void;close:()=>void;blendId:string;toast:(s:string)=>void}){
 const blend=db.blends.find(item=>item.id===blendId)!
 const [versionId,setVersionId]=useState(currentBest(blend).id)
 const version=blend.versions.find(item=>item.id===versionId)!
 const [rating,setRating]=useState(8)
 const [taste,setTaste]=useState<Taste>({...mkTaste(6)})
 const [notes,setNotes]=useState('')
 const [wouldMakeAgain,setWouldMakeAgain]=useState(true)
 const [saved,setSaved]=useState<{rating:number;delta:number|null;observation:string;next:string}|null>(null)
 const previousVersion=blend.versions.find(item=>item.number===version.number-1)
 const experimentNumber=version.experiments.length+1
 const experimentDate=new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'})
 function save(){
  const experiment:Experiment={id:uid('exp'),date:new Date().toISOString(),rating,taste,notes:`${notes}${notes?'\n\n':''}Would make again: ${wouldMakeAgain?'Yes':'Not yet'}`}
  const recommendation=recommend(experiment,version,previousVersion,db.pantry)
  experiment.recommendation=recommendation.suggestions[0]
  const nextDB={...db,blends:db.blends.map(item=>item.id===blend.id?{...item,versions:item.versions.map(candidate=>candidate.id===version.id?{...candidate,experiments:[...candidate.experiments,experiment]}:candidate)}:item)}
  const baseline=previousVersion?avgRating(previousVersion):avgRating(version)
  const delta=baseline?rating-baseline:null
  update({...nextDB,tasteProfile:avgTaste([...flattenExperiments(nextDB.blends)] as never)})
  setSaved({rating,delta,observation:notes||'No written observation was added.',next:recommendation.experimentIdea})
  toast('Tasting session saved.')
 }
 if(saved)return <div><ModalHeader eyebrow="Tasting session saved" title={`Version ${version.number} · Experiment ${experimentNumber}`} close={close}/><div className="mt-8 space-y-6"><div className="border-y border-line py-6"><div className="small-label">Result summary</div><div className="mt-4 flex flex-wrap items-end gap-x-8 gap-y-4"><div><div className="serif text-5xl">{saved.rating.toFixed(1)}</div><div className="text-xs text-soft">new rating / 10</div></div>{saved.delta!==null&&<div><div className={`serif text-4xl ${saved.delta>=0?'text-green':'text-rose'}`}>{saved.delta>=0?'+':''}{saved.delta.toFixed(1)}</div><div className="text-xs text-soft">rating difference from comparison</div></div>}</div></div><div className="border-l-2 border-caramel bg-subtle px-5 py-4"><div className="small-label">Key observation</div><p className="mt-2 text-sm leading-6 text-soft">{saved.observation}</p></div><div className="border-l-2 border-green bg-sage/30 px-5 py-4"><div className="small-label">Recommended next experiment</div><p className="mt-2 text-sm leading-6 text-soft">{saved.next}</p><p className="mt-2 text-xs text-soft">This is a possible next step based on the recorded taste signals; it does not establish causation.</p></div><button className="btn-primary w-full" onClick={close}>Done</button></div></div>
 return <div><ModalHeader eyebrow={`Experiment ${experimentNumber} · Tasting session`} title={`Make again · ${blend.name}`} close={close}/><div className="mt-6 space-y-8"><div className="grid gap-4 border-y border-line py-4 sm:grid-cols-2"><div><div className="small-label">Date</div><div className="mt-1 text-sm font-semibold">{experimentDate}</div></div><label className="block text-sm font-semibold">What did you make?<select value={versionId} onChange={event=>setVersionId(event.target.value)} className="ds-control mt-2 w-full">{blend.versions.map(item=><option key={item.id} value={item.id}>v{item.number} · {item.name}</option>)}</select></label></div><section><div className="small-label">Overall rating</div><div className="mt-4 grid gap-6 sm:grid-cols-[auto_1fr] sm:items-center"><div className="relative grid h-28 w-28 place-items-center rounded-full" style={{background:`conic-gradient(var(--color-accent-caramel) ${rating*10}%, var(--color-surface-subtle) 0)`}}><div className="grid h-20 w-20 place-items-center rounded-full bg-paper"><span className="serif text-4xl">{rating.toFixed(1)}</span></div></div><div><div className="flex items-baseline justify-between"><span className="text-sm text-soft">How did it taste overall?</span><span className="text-xs font-semibold text-soft">0–10</span></div><input aria-label="Overall rating" type="range" min="0" max="10" step=".1" value={rating} onChange={event=>setRating(Number(event.target.value))} className="taste-range mt-5 w-full"/></div></div></section><section><div className="small-label">Taste observations</div><p className="mt-2 text-sm leading-6 text-soft">Use the scales to capture the character of this pour, not to find a perfect score.</p><div className="mt-5 grid gap-x-8 gap-y-5 sm:grid-cols-2">{tasteLabels.map(([key,label])=>{const value=Number((taste as any)[key]||0);return <label key={key} className="block"><div className="flex items-baseline justify-between text-sm"><span className="font-semibold">{label}</span><span className="font-semibold text-green">{value.toFixed(0)}<span className="ml-1 text-xs font-normal text-soft">/10</span></span></div><div className="relative mt-3 h-5"><div className="absolute left-0 right-0 top-2 h-1 bg-line"/><div className="absolute left-0 top-2 h-1 bg-green" style={{width:`${value*10}%`}}/><input aria-label={`${label} observation`} type="range" min="0" max="10" step="1" value={value} onChange={event=>setTaste({...taste,[key]:Number(event.target.value)})} className="taste-range absolute inset-0 w-full"/></div><div className="mt-1 flex justify-between text-[10px] text-soft"><span>Low</span><span>High</span></div></label>})}</div></section><label className="block"><div className="small-label">What did you notice?</div><textarea autoFocus={false} value={notes} onChange={event=>setNotes(event.target.value)} rows={6} className="ds-control mt-3 min-h-36 w-full resize-y" placeholder="Texture, aroma, balance, what surprised you…"/></label><section className="border-y border-line py-5"><div className="small-label">Would you make this again?</div><div className="mt-3 flex gap-2"><button type="button" onClick={()=>setWouldMakeAgain(true)} className={`ds-button ${wouldMakeAgain?'ds-button-secondary !border-green !bg-sage/30':'ds-button-quiet'}`}>Yes, keep it in rotation</button><button type="button" onClick={()=>setWouldMakeAgain(false)} className={`ds-button ${!wouldMakeAgain?'ds-button-secondary !border-rose !bg-rose/5':'ds-button-quiet'}`}>Not yet</button></div></section><div className="flex justify-end border-t border-line pt-5"><button className="btn-primary w-full sm:w-auto" onClick={save}><Check size={17}/> Save tasting session</button></div></div></div>
}

function LegacyVariationModal({db,update,close,blendId,toast}:{db:DB;update:(d:DB)=>void;close:()=>void;blendId:string;toast:(s:string)=>void}){
 const blend=db.blends.find(b=>b.id===blendId)!; const base=currentBest(blend); const [change,setChange]=useState('Ingredient amount'); const [target,setTarget]=useState(base.ingredients[0]?.name||''); const [value,setValue]=useState(''); const options=['Ingredient amount','New ingredient','Different milk','Different sweetener','Different brand','Ice level','Temperature','Preparation method','Custom'];
 function save(){ let ingredients=base.ingredients.map(i=>({...i,id:uid('ing')})); if(change==='Ingredient amount'&&target&&value){ingredients=ingredients.map(i=>i.name===target?{...i,amount:Number(value)||i.amount}:i)} else if(change==='Different brand'&&target&&value){ingredients=ingredients.map(i=>i.name===target?{...i,brand:value}:i)} else if(change==='New ingredient'&&value){ingredients.push(makeIngredient(value,0,'ml'))} const v:Version={id:uid('v'),number:Math.max(...blend.versions.map(v=>v.number))+1,name:`Experiment ${Math.max(...blend.versions.map(v=>v.number))+1}`,createdAt:new Date().toISOString(),notes:`Variation from v${base.number}: ${change}${value?` — ${value}`:''}`,ingredients,preparation:base.preparation,experiments:[]}; update({...db,blends:db.blends.map(b=>b.id===blend.id?{...b,versions:[...b.versions,v]}:b)}); close(); toast(`v${v.number} created. Original versions stay untouched.`); }
 return <div><ModalHeader eyebrow={`Variation · Start from v${base.number}`} title="What should change?" close={close}/><p className="mt-3 text-sm text-soft">MyBlend preserves the previous recipe and records this as a new version.</p><div className="mt-5 flex flex-wrap gap-2">{options.map(o=><button key={o} onClick={()=>setChange(o)} className={`rounded-full border px-3 py-2 text-xs font-extrabold ${change===o?'border-green bg-sage/30':'border-line bg-cream text-soft'}`}>{o}</button>)}</div><div className="mt-5 rounded-3xl bg-cream p-5 space-y-4"><div className="small-label">Current version</div><div className="font-extrabold">v{base.number} · {base.name}</div>{(change==='Ingredient amount'||change==='Different brand')&&<label className="block text-sm font-bold">Ingredient<select value={target} onChange={e=>setTarget(e.target.value)} className="mt-2 w-full rounded-2xl border border-line bg-paper px-4 py-3">{base.ingredients.map(i=><option key={i.id} value={i.name}>{i.name} · {i.amount}{i.unit}</option>)}</select></label>}<label className="block text-sm font-bold">New value<input value={value} onChange={e=>setValue(e.target.value)} className="mt-2 w-full rounded-2xl border border-line bg-paper px-4 py-3" placeholder={change==='Ingredient amount'?'e.g. 45':change==='Different brand'?'e.g. Oatly':'Describe the change'}/></label><div className="rounded-2xl bg-paper p-4 text-sm leading-6 text-soft">Everything you do not change stays copied from v{base.number}. The new version can then be tested on its own.</div></div><div className="mt-7 flex justify-end gap-2 border-t border-line pt-5"><button className="btn-secondary" onClick={close}>Cancel</button><button className="btn-primary" onClick={save}><GitCompare size={16}/> Create New Version</button></div></div>
}

function VariationModal({db,update,close,blendId,toast}:{db:DB;update:(d:DB)=>void;close:()=>void;blendId:string;toast:(s:string)=>void}){
 const blend=db.blends.find(item=>item.id===blendId)!
 const base=currentBest(blend)
 const nextNumber=Math.max(...blend.versions.map(item=>item.number))+1
 const [change,setChange]=useState('Ingredient amount')
 const [target,setTarget]=useState(base.ingredients[0]?.name||'')
 const [value,setValue]=useState('')
 const [error,setError]=useState('')
 const options=['Ingredient amount','New ingredient','Milk','Sweetener','Brand','Ice','Temperature','Preparation','Custom']
 const selectedIngredient=base.ingredients.find(item=>item.name===target)
 const previewLabel=change==='Ingredient amount'||change==='Brand'?target||'Select an ingredient':change==='New ingredient'?'New ingredient':change
 const beforeValue=change==='Ingredient amount'||change==='Brand'?(selectedIngredient?(change==='Brand'?(selectedIngredient.brand||'House brand'):`${selectedIngredient.amount}${selectedIngredient.unit}`):'Select an ingredient'):change==='Preparation'?base.preparation:'Current recipe'
 const afterValue=value||(change==='New ingredient'?'Add a new ingredient':change==='Preparation'?'Describe the preparation change':`Your ${change.toLowerCase()} change`)
 function save(){
  if(!value.trim()){setError('Describe the change before creating the next version.');return}
  let ingredients=base.ingredients.map(item=>({...item,id:uid('ing')}))
  if(change==='Ingredient amount'&&target&&value){ingredients=ingredients.map(item=>item.name===target?{...item,amount:Number(value)||item.amount}:item)}
  else if(change==='Brand'&&target&&value){ingredients=ingredients.map(item=>item.name===target?{...item,brand:value}:item)}
  else if(change==='New ingredient'&&value){ingredients.push(makeIngredient(value,0,'ml'))}
  const version:Version={id:uid('v'),number:nextNumber,name:`Experiment ${nextNumber}`,createdAt:new Date().toISOString(),notes:`Variation from v${base.number}: ${change} — ${value}`,ingredients,preparation:base.preparation,experiments:[]}
  update({...db,blends:db.blends.map(item=>item.id===blend.id?{...item,versions:[...item.versions,version]}:item)})
  close();toast(`Version ${version.number} created. Previous versions stay unchanged.`)
 }
 return <div><div className="flex items-start justify-between gap-4"><div><div className="small-label">Recipe variation</div><h2 className="serif mt-2 text-4xl font-semibold">Start from Version {base.number}</h2><p className="mt-3 max-w-lg text-sm leading-6 text-soft">Your previous recipe remains exactly as it was. This new version will record one focused change.</p></div><button className="btn-ghost p-2" onClick={close} aria-label="Close variation flow"><X size={19}/></button></div><div className="mt-7 border-y border-line py-5"><div className="small-label">What do you want to experiment with?</div><div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-3">{options.map(option=><button type="button" key={option} onClick={()=>{setChange(option);setValue('');setError('')}} className={`border px-3 py-3 text-left text-sm transition ${change===option?'border-green bg-sage/30 font-semibold':'border-line bg-cream hover:border-caramel'}`}>{option}</button>)}</div></div><div className="mt-7"><div className="small-label">One variable changed</div><div className="mt-3 grid items-center gap-3 sm:grid-cols-[1fr_auto_1fr]"><div className="border-l-2 border-line bg-cream px-4 py-4"><div className="text-xs text-soft">Before</div><div className="mt-2 font-semibold">{previewLabel}</div><div className="mt-1 text-sm text-soft">{beforeValue}</div></div><ChevronDown className="mx-auto text-caramel sm:rotate-[-90deg]" size={20}/><div className="border-l-2 border-caramel bg-caramel-soft/30 px-4 py-4"><div className="text-xs text-soft">After</div><div className="mt-2 font-semibold">{previewLabel}</div><div className="mt-1 text-sm text-espresso">{afterValue}</div></div></div></div><div className="mt-7 space-y-4 border-t border-line pt-6">{(change==='Ingredient amount'||change==='Brand')&&<label className="block text-sm font-semibold">Ingredient<select value={target} onChange={event=>setTarget(event.target.value)} className="ds-control mt-2 w-full">{base.ingredients.map(item=><option key={item.id} value={item.name}>{item.name} · {item.amount}{item.unit}</option>)}</select></label>}{change==='Ingredient amount'&&<label className="block text-sm font-semibold">New amount<input autoFocus type="number" min="0" value={value} onChange={event=>{setValue(event.target.value);setError('')}} className="ds-control mt-2 w-full" placeholder={selectedIngredient?`${selectedIngredient.amount}`:'10'}/></label>}{change==='Brand'&&<label className="block text-sm font-semibold">New brand<input autoFocus value={value} onChange={event=>{setValue(event.target.value);setError('')}} className="ds-control mt-2 w-full" placeholder="Oatly, Monin, House Arabica…"/></label>}{change==='New ingredient'&&<label className="block text-sm font-semibold">Ingredient to add<input autoFocus value={value} onChange={event=>{setValue(event.target.value);setError('')}} className="ds-control mt-2 w-full" placeholder="Cinnamon, orange peel, tonic…"/></label>}{change!=='Ingredient amount'&&change!=='Brand'&&change!=='New ingredient'&&<label className="block text-sm font-semibold">Describe the change<input autoFocus value={value} onChange={event=>{setValue(event.target.value);setError('')}} className="ds-control mt-2 w-full" placeholder={change==='Preparation'?'Whisk before adding milk':'What will you try?'}/></label>}{error&&<div className="border-l-2 border-rose bg-rose/5 px-4 py-3 text-sm text-rose">{error}</div>}</div><div className="mt-7 border-t border-line pt-5"><div className="flex items-start gap-3 text-sm text-soft"><Check size={17} className="mt-0.5 shrink-0 text-green"/><p>Version {base.number} is preserved. Create Version {nextNumber} to test this change separately.</p></div><div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><button className="btn-secondary" onClick={close}>Cancel</button><button className="btn-primary" onClick={save}><GitCompare size={16}/> Create Version {nextNumber}</button></div></div></div>
}

function LegacyPantryModal({db,update,close}:{db:DB;update:(d:DB)=>void;close:()=>void}){const [name,setName]=useState('');const [quantity,setQuantity]=useState(100);const [unit,setUnit]=useState('ml');const [threshold,setThreshold]=useState(30);const [expiry,setExpiry]=useState('');function save(){if(!name.trim())return;const item:PantryItem={id:uid('pantry'),name:name.trim(),quantity,unit,threshold,expiry:expiry?new Date(expiry).toISOString():undefined};update({...db,pantry:[item,...db.pantry]});close()}return <div><ModalHeader eyebrow="Pantry" title="Add ingredient" close={close}/><div className="mt-6 space-y-4"><label className="block text-sm font-bold">Ingredient name<input value={name} onChange={e=>setName(e.target.value)} className="mt-2 w-full rounded-2xl border border-line bg-cream px-4 py-3" placeholder="Oat Milk"/></label><div className="grid grid-cols-2 gap-3"><label className="block text-sm font-bold">Quantity<input type="number" value={quantity} onChange={e=>setQuantity(Number(e.target.value))} className="mt-2 w-full rounded-2xl border border-line bg-cream px-4 py-3"/></label><label className="block text-sm font-bold">Unit<input value={unit} onChange={e=>setUnit(e.target.value)} className="mt-2 w-full rounded-2xl border border-line bg-cream px-4 py-3"/></label></div><div className="grid grid-cols-2 gap-3"><label className="block text-sm font-bold">Low-stock threshold<input type="number" value={threshold} onChange={e=>setThreshold(Number(e.target.value))} className="mt-2 w-full rounded-2xl border border-line bg-cream px-4 py-3"/></label><label className="block text-sm font-bold">Expiry (optional)<input type="date" value={expiry} onChange={e=>setExpiry(e.target.value)} className="mt-2 w-full rounded-2xl border border-line bg-cream px-4 py-3"/></label></div></div><div className="mt-7 flex justify-end gap-2 border-t border-line pt-5"><button className="btn-secondary" onClick={close}>Cancel</button><button className="btn-primary" onClick={save}><Check size={16}/> Add to Pantry</button></div></div>}

function CompareModal({db,close,blendId}:{db:DB;close:()=>void;blendId:string}){const blend=db.blends.find(b=>b.id===blendId)!;const [a,setA]=useState(blend.versions[0].id);const [b,setB]=useState(blend.versions.at(-1)!.id);const va=blend.versions.find(v=>v.id===a)!;const vb=blend.versions.find(v=>v.id===b)!;const diffs=versionDiff(va,vb);const da=avgTaste(va.experiments),dbb=avgTaste(vb.experiments);const delta=avgRating(vb)-avgRating(va);return <div><ModalHeader eyebrow="Comparison mode" title={`v${va.number} vs v${vb.number}`} close={close}/><div className="mt-5 grid grid-cols-2 gap-3"><select value={a} onChange={e=>setA(e.target.value)} className="rounded-2xl border border-line bg-cream px-4 py-3 text-sm font-bold">{blend.versions.map(v=><option key={v.id} value={v.id}>v{v.number} · {v.name}</option>)}</select><select value={b} onChange={e=>setB(e.target.value)} className="rounded-2xl border border-line bg-cream px-4 py-3 text-sm font-bold">{blend.versions.map(v=><option key={v.id} value={v.id}>v{v.number} · {v.name}</option>)}</select></div><div className="mt-5 grid grid-cols-2 gap-3"><div className="rounded-3xl bg-cream p-5"><div className="small-label">v{va.number} rating</div><div className="serif mt-1 text-4xl font-semibold">{avgRating(va).toFixed(1)}</div></div><div className="rounded-3xl bg-sage/30 p-5"><div className="small-label">v{vb.number} rating</div><div className="serif mt-1 text-4xl font-semibold">{avgRating(vb).toFixed(1)}</div></div></div><div className="mt-4 rounded-3xl border border-line p-5"><div className="small-label">What changed?</div><div className="mt-4 space-y-3">{diffs.length?diffs.map(d=><div key={d.name} className="flex items-center justify-between gap-3 text-sm"><div className="font-extrabold">{d.name}</div><div className="flex items-center gap-2"><span className="rounded-xl bg-cream px-3 py-2 font-bold">{d.from}</span><ArrowRight size={14}/><span className="rounded-xl bg-sage px-3 py-2 font-extrabold text-green">{d.to}</span></div></div>):<div className="text-sm text-soft">No ingredient differences recorded between these versions.</div>}</div></div><div className="mt-4 grid grid-cols-2 gap-3">{(['sweetness','strength','creaminess','richness','refreshing','bitterness'] as const).map(k=><div key={k} className="rounded-2xl bg-cream p-4"><div className="text-[10px] font-extrabold uppercase tracking-wide text-soft">{k}</div><div className="mt-1 flex justify-between text-sm font-extrabold"><span>{(da as any)[k]?.toFixed?.(1)??0}</span><span className={((dbb as any)[k]??0)>((da as any)[k]??0)?'text-green':'text-rose'}>{((dbb as any)[k]??0).toFixed?.(1)??0}</span></div></div>)}</div><div className="mt-5 rounded-3xl bg-espresso p-5 text-paper"><div className="small-label !text-caramel-soft">Rating movement</div><div className="mt-1 font-extrabold">{delta>=0?`The selected later version is +${delta.toFixed(1)} points higher.`:`The selected later version is ${Math.abs(delta).toFixed(1)} points lower.`}</div><p className="mt-2 text-xs leading-5 text-paper/60">This describes the recorded rating difference; it does not claim that one ingredient caused the change.</p></div></div>}
